-- ============================================================
-- PREVIOUS RUN TEARDOWN
-- ============================================================
local Genv = typeof(getgenv) == "function" and getgenv() or _G

local PreviousRun = Genv.LinhUBG
if type(PreviousRun) == "table" and type(PreviousRun.Unload) == "function" then
	pcall(PreviousRun.Unload)
end

pcall(function()
	if Genv.dodge then Genv.dodge:Disconnect(); Genv.dodge = nil end
end)
pcall(function()
	if Genv.dodgeChar then Genv.dodgeChar:Disconnect(); Genv.dodgeChar = nil end
end)

local Running = true
local CleanupTasks = {}
local function onCleanup(fn)
	table.insert(CleanupTasks, fn)
end

local function fullUnload()
	if not Running then return end
	Running = false
	for i = #CleanupTasks, 1, -1 do
		pcall(CleanupTasks[i])
	end
	pcall(function() Genv.LinhUBG = nil end)
	print("[LINH] Untitled Boxing Game unloaded")
end

Genv.LinhUBG = { Unload = fullUnload }

