	-- Tweening
	local Tween = {}
	do
		Tween.__index = Tween

		Tween.Create = function(self, Item, Info, Goal, IsRawItem)
			Item = IsRawItem and Item or Item.Instance
			Info = Info or TweenInfo.new(Library.Tween.Time, Library.Tween.Style, Library.Tween.Direction)

			local NewTween = {
				Tween = TweenService:Create(Item, Info, Goal),
				Info = Info,
				Goal = Goal,
				Item = Item,
			}

			NewTween.Tween:Play()

			setmetatable(NewTween, Tween)

			return NewTween
		end

		Tween.GetProperty = function(self, Item)
			Item = Item or self.Item

			if Item:IsA("Frame") then
				return { "BackgroundTransparency" }
			elseif Item:IsA("TextLabel") or Item:IsA("TextButton") then
				return { "TextTransparency", "BackgroundTransparency" }
			elseif Item:IsA("ImageLabel") or Item:IsA("ImageButton") then
				return { "BackgroundTransparency", "ImageTransparency" }
			elseif Item:IsA("ScrollingFrame") then
				return { "BackgroundTransparency", "ScrollBarImageTransparency" }
			elseif Item:IsA("TextBox") then
				return { "TextTransparency", "BackgroundTransparency" }
			elseif Item:IsA("UIStroke") then
				return { "Transparency" }
			end
		end

		Tween.FadeItem = function(self, Item, Property, Visibility, Speed)
			local Item = Item or self.Item

			local OldTransparency = Item[Property]
			Item[Property] = Visibility and 1 or OldTransparency

			local NewTween = Tween:Create(
				Item,
				TweenInfo.new(Speed or Library.Tween.Time, Library.Tween.Style, Library.Tween.Direction),
				{
					[Property] = Visibility and OldTransparency or 1,
				},
				true
			)

			Library:Connect(NewTween.Tween.Completed, function()
				if not Visibility then
					-- Tween.Completed fires after the animation; no extra task.wait() is needed.
					-- Avoids a nil-call if an obfuscator/executor changes the task environment.
					Item[Property] = OldTransparency
				end
			end)

			return NewTween
		end

		Tween.Get = function(self)
			if not self.Tween then
				return
			end

			return self.Tween, self.Info, self.Goal
		end

		Tween.Pause = function(self)
			if not self.Tween then
				return
			end

			self.Tween:Pause()
		end

		Tween.Play = function(self)
			if not self.Tween then
				return
			end

			self.Tween:Play()
		end

		Tween.Clean = function(self)
			if not self.Tween then
				return
			end

			Tween:Pause()
			self = nil
		end
	end

	-- Instances
	local Instances = {}
	do
		Instances.__index = Instances

		Instances.Create = function(self, Class, Properties)
			local NewItem = {
				Instance = InstanceNew(Class),
				Properties = Properties,
				Class = Class,
			}

			setmetatable(NewItem, Instances)

			for Property, Value in next, NewItem.Properties do
				NewItem.Instance[Property] = Value
			end

			return NewItem
		end

		Instances.FadeItem = function(self, Visibility, Speed)
			local Item = self.Instance

			if Visibility == true then
				Item.Visible = true
			end

			local Descendants = Item:GetDescendants()
			TableInsert(Descendants, Item)

			local NewTween

			for Index, Value in next, Descendants do
				local TransparencyProperty = Tween:GetProperty(Value)

				if TransparencyProperty then
					if type(TransparencyProperty) == "table" then
						for Index, Property in next, TransparencyProperty do
							NewTween = Tween:FadeItem(Value, Property, not Visibility, Speed)
						end
					else
						NewTween = Tween:FadeItem(Value, TransparencyProperty, not Visibility, Speed)
					end
				end
			end
		end

		Instances.AddToTheme = function(self, Properties)
			if not self.Instance then
				return
			end

			Library:AddToTheme(self, Properties)
		end

		Instances.ChangeItemTheme = function(self, Properties)
			if not self.Instance then
				return
			end

			Library:ChangeItemTheme(self, Properties)
		end

		Instances.Connect = function(self, Event, Callback, Name)
			if not self.Instance then
				return
			end

			if not self.Instance[Event] then
				return
			end

			if IsMobile then
				if Event == "MouseButton1Down" or Event == "MouseButton1Click" then
					Event = "TouchTap"
				elseif Event == "MouseButton2Down" or Event == "MouseButton2Click" then
					Event = "TouchLongPress"
				end
			end

			return Library:Connect(self.Instance[Event], Callback, Name)
		end

		Instances.Tween = function(self, Info, Goal)
			if not self.Instance then
				return
			end

			return Tween:Create(self, Info, Goal)
		end

		Instances.Disconnect = function(self, Name)
			if not self.Instance then
				return
			end

			return Library:Disconnect(Name)
		end

		Instances.Clean = function(self)
			if not self.Instance then
				return
			end

			self.Instance:Destroy()
			self = nil
		end

		Instances.MakeDraggable = function(self)
			if not self.Instance then
				return
			end

			local Gui = self.Instance
			Gui.Active = true
			local Dragging = false
			local DragStart
			local StartAbsPos

			local DragOffset
			local GuiInsetY = game:GetService("GuiService"):GetGuiInset().Y

			local Set = function(Input)
				local NewAbsX = Mouse.X - DragOffset.X
				local NewAbsY = Mouse.Y - DragOffset.Y

				local ScreenSize = Gui.Parent.AbsoluteSize
				local GuiSize = Gui.AbsoluteSize

				-- Calculate actual visual height including overflow children (e.g. tab bar).
				local VisualHeight = GuiSize.Y
				for Index, Child in next, Gui:GetChildren() do
					if Child:IsA("GuiObject") and Child.Visible then
						local ChildBottom = (Child.AbsolutePosition.Y - Gui.AbsolutePosition.Y) + Child.AbsoluteSize.Y
						if ChildBottom > VisualHeight then
							VisualHeight = ChildBottom
						end
					end
				end

				NewAbsX = MathClamp(NewAbsX, 0, ScreenSize.X - GuiSize.X)
				NewAbsY = MathClamp(NewAbsY, -GuiInsetY, ScreenSize.Y - VisualHeight - GuiInsetY)

				-- Convert viewport coords to IgnoreGuiInset Position offset (screen coords).
				local Anchor = Gui.AnchorPoint
				local OffsetX = NewAbsX + Anchor.X * GuiSize.X
				local OffsetY = NewAbsY + GuiInsetY + Anchor.Y * GuiSize.Y

				self:Tween(
					TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(0, OffsetX, 0, OffsetY) }
				)
			end

			local InputChanged

			self:Connect("InputBegan", function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseButton1
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					Library.DragLock = true
					Dragging = true
					-- Store offset from element top-left to mouse position.
					DragOffset = Vector2New(Mouse.X - Gui.AbsolutePosition.X, Mouse.Y - Gui.AbsolutePosition.Y)

					if InputChanged then
						return
					end

					InputChanged = Input.Changed:Connect(function()
						if Input.UserInputState == Enum.UserInputState.End then
							Dragging = false
							Library.DragLock = false
							InputChanged:Disconnect()
							InputChanged = nil
						end
					end)
				end
			end)

			Library:Connect(UserInputService.InputChanged, function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseMovement
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					if Dragging then
						Set(Input)
					end
				end
			end)

			return Dragging
		end

		Instances.MakeResizeable = function(self, Minimum, Maximum, Window)
			if not self.Instance then
				return
			end

			local Gui = self.Instance

			local Resizing = false
			local CurrentSide = nil

			local StartMouse = nil
			local StartPosition = nil
			local StartSize = nil

			local EdgeThickness = 2

			local MakeEdge = function(Name, Position, Size)
				local Button = Instances:Create("TextButton", {
					Name = "\0",
					Size = Size,
					Position = Position,
					BackgroundColor3 = FromRGB(166, 147, 243),
					BackgroundTransparency = 1,
					Text = "",
					BorderSizePixel = 0,
					AutoButtonColor = false,
					Parent = Gui,
					ZIndex = 99999,
				})
				Button:AddToTheme({ BackgroundColor3 = "Accent" })

				return Button
			end

			local Edges = {
				{
					Button = MakeEdge("Left", UDim2New(0, 0, 0, 0), UDim2New(0, EdgeThickness, 1, 0)),
					Side = "L",
				},

				{
					Button = MakeEdge("Right", UDim2New(1, -EdgeThickness, 0, 0), UDim2New(0, EdgeThickness, 1, 0)),
					Side = "R",
				},

				{
					Button = MakeEdge("Top", UDim2New(0, 0, 0, 0), UDim2New(1, 0, 0, EdgeThickness)),
					Side = "T",
				},

				{
					Button = MakeEdge("Bottom", UDim2New(0, 0, 1, -EdgeThickness), UDim2New(1, 0, 0, EdgeThickness)),
					Side = "B",
				},
			}

			local BeginResizing = function(Side)
				Resizing = true
				CurrentSide = Side

				StartMouse = UserInputService:GetMouseLocation()

				-- store offsets, not absolute screen pos
				StartPosition = Vector2New(Gui.Position.X.Offset, Gui.Position.Y.Offset)
				StartSize = Vector2New(Gui.Size.X.Offset, Gui.Size.Y.Offset)

				for Index, Value in next, Edges do
					Value.Button:Tween(nil, { BackgroundTransparency = (Value.Side == Side) and 0 or 1 })
				end
			end

			local EndResizing = function()
				Resizing = false
				CurrentSide = nil

				for Index, Value in next, Edges do
					Value.Button.Instance.BackgroundTransparency = 1
				end
			end

			for Index, Value in next, Edges do
				Value.Button:Connect("InputBegan", function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 then
						BeginResizing(Value.Side)
					end
				end)
			end

			Library:Connect(UserInputService.InputEnded, function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					if Resizing then
						EndResizing()
					end
				end
			end)

			Library:Connect(RunService.RenderStepped, function()
				if not Resizing or not CurrentSide then
					return
				end

				local MouseLocation = UserInputService:GetMouseLocation()
				local Dx = MouseLocation.X - StartMouse.X
				local Dy = MouseLocation.Y - StartMouse.Y

				local X, Y = StartPosition.X, StartPosition.Y
				local W, H = StartSize.X, StartSize.Y

				if CurrentSide == "L" then
					X = StartPosition.X + Dx
					W = StartSize.X - Dx

					if Window then
						Window.Left.Y = H
					end
				elseif CurrentSide == "R" then
					W = StartSize.X + Dx

					if Window then
						Window.Right.Y = H
					end
				elseif CurrentSide == "T" then
					Y = StartPosition.Y + Dy
					H = StartSize.Y - Dy

					if Window then
						Window.Top.X = W
					end
				elseif CurrentSide == "B" then
					H = StartSize.Y + Dy

					if Window then
						Window.Bottom.X = W
					end
				end

				if W < Minimum.X then
					if CurrentSide == "L" then
						X = X - (Minimum.X - W)
					end
					W = Minimum.X
				end
				if H < Minimum.Y then
					if CurrentSide == "T" then
						Y = Y - (Minimum.Y - H)
					end
					H = Minimum.Y
				end

				self:Tween(
					TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2FromOffset(X, Y) }
				)
				self:Tween(
					TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Size = UDim2FromOffset(W, H) }
				)
			end)
		end

		Instances.OnHover = function(self, Function)
			if not self.Instance then
				return
			end

			return Library:Connect(self.Instance.MouseEnter, function()
				-- Suppress hover when mouse is over an open dropdown.
				if Library:IsMouseOverOpenDropdown() then
					return
				end
				Function()
			end)
		end

		Instances.OnHoverLeave = function(self, Function)
			if not self.Instance then
				return
			end

			-- Always fire leave — never suppress cleanup.
			return Library:Connect(self.Instance.MouseLeave, Function)
		end
	end

	-- Custom font
	local CustomFont = {}
	do
		function CustomFont:New(Name, Weight, Style, Data)
			if not isfile(Data.Id) then
				writefile(Data.Id, game:HttpGet(Data.Url))
			end

			local Data = {
				name = Name,
				faces = {
					{
						name = Name,
						weight = Weight,
						style = Style,
						assetId = getcustomasset(Data.Id),
					},
				},
			}

			writefile(Library.Folders.Assets .. "/" .. Name .. ".font", HttpService:JSONEncode(Data))
			return getcustomasset(Library.Folders.Assets .. "/" .. Name .. ".font")
		end

		local SemiBold = Font.new("rbxassetid://12187365364", Enum.FontWeight.SemiBold, Enum.FontStyle.Normal)

		local Regular = Font.new("rbxassetid://12187365364", Enum.FontWeight.Regular, Enum.FontStyle.Normal)

		local Light = Font.new("rbxassetid://12187365364", Enum.FontWeight.Light, Enum.FontStyle.Normal)

		Library.Fonts = {
			["SemiBold"] = SemiBold,
			["Regular"] = Regular,
			["Light"] = Light,
		}

		Library.Font = SemiBold
	end

	-- GUI protection: parent to CoreGui first, then move to gethui() for double-layer hiding.
	local CoreGui = game:GetService("CoreGui")
	local HolderDisplayOrder = 1000
	local OverlayDisplayOrder = HolderDisplayOrder + 1

	Library.Holder = Instances:Create("ScreenGui", {
		Parent = CoreGui,
		Name = "\0",
		ZIndexBehavior = Enum.ZIndexBehavior.Global,
		IgnoreGuiInset = true,
		DisplayOrder = HolderDisplayOrder,
		ResetOnSpawn = false,
	})
	Library.Holder.Instance.Parent = gethui()

	Library.DragLock = false

	Library.UnusedHolder = Instances:Create("ScreenGui", {
		Parent = CoreGui,
		Name = "\0",
		ZIndexBehavior = Enum.ZIndexBehavior.Global,
		DisplayOrder = HolderDisplayOrder,
		Enabled = false,
		ResetOnSpawn = false,
	})
	Library.UnusedHolder.Instance.Parent = gethui()

	Library.OverlayHolder = Instances:Create("ScreenGui", {
		Parent = CoreGui,
		Name = "\0",
		ZIndexBehavior = Enum.ZIndexBehavior.Global,
		DisplayOrder = OverlayDisplayOrder,
		ResetOnSpawn = false,
	})
	Library.OverlayHolder.Instance.Parent = gethui()

	Library.NotifHolder = Instances:Create("Frame", {
		Parent = Library.OverlayHolder.Instance,
		Name = "\0",
		BackgroundTransparency = 1,
		Size = UDim2New(0, 0, 1, 0),
		BorderColor3 = FromRGB(0, 0, 0),
		BorderSizePixel = 0,
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundColor3 = FromRGB(255, 255, 255),
	})

	Instances:Create("UIListLayout", {
		Parent = Library.NotifHolder.Instance,
		Name = "\0",
		Padding = UDimNew(0, 12),
		SortOrder = Enum.SortOrder.LayoutOrder,
	})

	Instances:Create("UIPadding", {
		Parent = Library.NotifHolder.Instance,
		Name = "\0",
		PaddingTop = UDimNew(0, 12),
		PaddingBottom = UDimNew(0, 12),
		PaddingRight = UDimNew(0, 12),
		PaddingLeft = UDimNew(0, 12),
	})

	Library.Unload = function(self)
		-- Kill simulation guard so hitbox loop dies.
		getgenv().__EP_SimulationSession = nil

		-- Unload embedded scripts via their module Unload() functions.
		local function UnloadScriptModules(ScriptModules)
			if type(ScriptModules) ~= "table" then
				return
			end

			for Index, Module in next, ScriptModules do
				pcall(function()
					if Module and Module.Unload then
						Module.Unload()
					end
				end)
				ScriptModules[Index] = nil
			end
		end

		local function CleanupMCPBridgeTables()
			if not getgc then
				return
			end

			for Index, Candidate in next, getgc(true) do
				if type(Candidate) ~= "table" then
					continue
				end

				local Callbacks = rawget(Candidate, "Callbacks")
				if type(Callbacks) ~= "table" then
					continue
				end
				if not rawget(Callbacks, "execute") or not rawget(Callbacks, "get-data-by-code") then
					continue
				end
				if rawget(Candidate, "WrathOwned") ~= true then
					continue
				end

				local Destroy = rawget(Candidate, "Destroy")
				if Destroy then
					pcall(Destroy, Candidate)
				else
					rawset(Candidate, "Connected", false)

					local AliveThread = rawget(Candidate, "AliveThread")
					if AliveThread then
						pcall(task.cancel, AliveThread)
					end

					local PollThread = rawget(Candidate, "PollThread")
					if PollThread then
						pcall(task.cancel, PollThread)
					end

					local Connections = rawget(Candidate, "Connections")
					if type(Connections) == "table" then
						for ConnectionIndex, Connection in next, Connections do
							pcall(function()
								Connection:Disconnect()
							end)
							Connections[ConnectionIndex] = nil
						end
					end

					local WebSocket = rawget(Candidate, "WebSocket")
					if WebSocket then
						pcall(function()
							WebSocket:Close()
						end)
					end
				end
			end
		end

		UnloadScriptModules(self._ScriptModules)
		UnloadScriptModules(getgenv().__WrathScriptModules)
		self._ScriptModules = nil
		getgenv().__WrathScriptModules = nil

		pcall(function()
			local Shutdown = getgenv().__WrathMCPConnectorShutdown
			if Shutdown then
				Shutdown()
			end
		end)
		getgenv().__WrathMCPConnectorShutdown = nil
		pcall(CleanupMCPBridgeTables)

		pcall(function()
			local Cobalt = getgenv().Cobalt
			if Cobalt and Cobalt.shared and Cobalt.shared.Unload then
				Cobalt.shared.Unload()
			end
		end)
		getgenv().Cobalt = nil
		getgenv().CobaltInitialized = nil
		getgenv().CobaltAutoExecuted = nil
		getgenv().IY_LOADED = nil
		getgenv().VexExecutedCheck = false

		-- Disconnect all connections.
		for Index, Value in next, self.Connections do
			pcall(function()
				Value.Connection:Disconnect()
			end)
		end

		for Index, Value in next, self.Threads do
			pcall(coroutine.close, Value)
		end

		-- Destroy all GUI holders.
		pcall(function()
			if self.Holder then
				self.Holder:Clean()
			end
		end)
		pcall(function()
			if self.OverlayHolder then
				self.OverlayHolder:Clean()
			end
		end)

		-- Destroy glass parts in camera.
		pcall(function()
			for Index, Child in next, workspace.CurrentCamera:GetChildren() do
				if Child:IsA("Part") and Child.Material == Enum.Material.Glass then
					Child:Destroy()
				end
			end
		end)

		-- Destroy DOF and blur in lighting.
		pcall(function()
			for Index, Child in next, game:GetService("Lighting"):GetChildren() do
				if Child:IsA("DepthOfFieldEffect") or (Child:IsA("BlurEffect") and Child.Name:find("__EP_")) then
					Child:Destroy()
				end
			end
		end)

		-- Destroy hitbox simulation parts.
		pcall(function()
			for Index, Child in next, workspace:GetChildren() do
				if Child:IsA("Part") and Child.Name == "__EP_HitboxSim" then
					Child:Destroy()
				end
			end
		end)

		-- Destroy info logger.
		pcall(function()
			local CoreGuiRef = game:GetService("CoreGui")
			local Prev = CoreGuiRef:FindFirstChild("__EP_InfoLogger")
			if Prev then
				Prev:Destroy()
			end
		end)
		pcall(function()
			local Prev = game.Players.LocalPlayer.PlayerGui:FindFirstChild("__EP_InfoLogger")
			if Prev then
				Prev:Destroy()
			end
		end)

		-- Stop music.
		pcall(function()
			for Index, SoundObj in next, game:GetService("SoundService"):GetChildren() do
				if SoundObj:IsA("Sound") and SoundObj.Name == "__Wrath_bgm_0xCAFE" then
					SoundObj:Stop()
					SoundObj:Destroy()
				end
			end
		end)

		-- Destroy animation visualizer.
		pcall(function()
			local CoreGuiRef = game:GetService("CoreGui")
			for Index, Child in next, CoreGuiRef:GetChildren() do
				if Child:IsA("ScreenGui") and Child.Name == "AnimationVisualizer" then
					Child:Destroy()
				end
			end
		end)

		self.InfoLogger = nil
		Library = nil
		getgenv().Library = nil
		getgenv()._WrathLib = nil
	end

	-- Info Logger delegates. Wired to Core/InfoLogger at runtime.
	Library.InfoLogger = nil

	Library.AddMissEntry = function(self, type, key, name, distance, parent, entity)
		if self.InfoLogger then
			pcall(self.InfoLogger.AddMissEntry, type, key, name, distance, parent, entity)
		end
	end

	Library.AddExistingEntry = function(self, type, key, name, distance, parent, entity)
		if self.InfoLogger then
			pcall(self.InfoLogger.AddExistingEntry, type, key, name, distance, parent, entity)
		end
	end

	Library.RefreshInfoLogger = function(self)
		if self.InfoLogger then
			pcall(self.InfoLogger.Refresh)
		end
	end

	Library.KeyBlacklists = function(self)
		if self.InfoLogger then
			return self.InfoLogger.GetBlacklists()
		end
		return {}
	end

	Library.GetImage = function(self, Image)
		local ImageData = self.Images[Image]

		if not ImageData then
			return
		end

		return getcustomasset(self.Folders.Assets .. "/" .. ImageData[1])
	end

	Library.Round = function(self, Number, Float)
		local Multiplier = 1 / (Float or 1)
		return MathFloor(Number * Multiplier) / Multiplier
	end

	Library.Thread = function(self, Function)
		local NewThread = coroutine.create(Function)

		coroutine.wrap(function()
			coroutine.resume(NewThread)
		end)()

		TableInsert(self.Threads, NewThread)
		return NewThread
	end

	Library.SafeCall = function(self, Function, ...)
		local Arguements = { ... }
		local Success, Result = pcall(Function, TableUnpack(Arguements))

		if not Success then
			warn(Result)
			return false
		end

		return Success
	end

	Library.Connect = function(self, Event, Callback, Name)
		Name = Name
			or StringFormat("connection_number_%s_%s", self.UnnamedConnections + 1, HttpService:GenerateGUID(false))

		local NewConnection = {
			Event = Event,
			Callback = Callback,
			Name = Name,
			Connection = nil,
		}

		-- Guard every connection callback: a throwing handler is caught and logged, never propagated.
		local function OnConnectionError(ConnectionError)
			local ErrorText = tostring(ConnectionError)
			local Traceback = ""
			if debug and type(debug.traceback) == "function" then
				Traceback = "\n" .. debug.traceback(ErrorText, 2)
			end
			warn(StringFormat("[Wrath] Library connection error (%s; callback=%s): %s%s", Name, type(Callback), ErrorText, Traceback))
		end

		Library:Thread(function()
			NewConnection.Connection = Event:Connect(function(...)
				return xpcall(Callback, OnConnectionError, ...)
			end)
		end)

		TableInsert(self.Connections, NewConnection)
		return NewConnection
	end

	Library.Disconnect = function(self, Name)
		for Index, Connection in next, self.Connections do
			if Connection.Name == Name then
				Connection.Connection:Disconnect()
				break
			end
		end
	end

	Library.NextFlag = function(self)
		local FlagNumber = self.UnnamedFlags + 1
		return StringFormat("flag_number_%s_%s", FlagNumber, HttpService:GenerateGUID(false))
	end

	---Add marquee (scroll-on-hover) behavior to a TextLabel inside a clipped container.
	---@param Container GuiObject The clipping parent (must have ClipsDescendants = true).
	---@param TextLabel TextLabel The text element to scroll.
	Library.MakeMarquee = function(self, Container, TextLabel, Guard)
		Container.ClipsDescendants = true
		local Scrolling = false
		local ScrollThread = nil
		local RestorePos = nil
		local Hovering = false

		Library:Connect(Container.MouseEnter, function()
			-- Guard: skip if caller says not ready (e.g. dropdown still animating).
			if Guard and not Guard() then
				return
			end

			Hovering = true

			-- Wait for position to stabilize (slide-in tweens may still be running).
			local PosA = TextLabel.AbsolutePosition.X
			task.wait(0.05)
			if not Hovering then
				return
			end
			local PosB = TextLabel.AbsolutePosition.X
			if MathAbs(PosA - PosB) > 0.5 then
				return
			end

			local ContainerWidth = Container.AbsoluteSize.X
			-- Use AbsolutePosition to get the true visual offset (handles nested parents).
			local TextStartX = TextLabel.AbsolutePosition.X - Container.AbsolutePosition.X
			local TextWidth = TextLabel.TextBounds.X
			if TextWidth + TextStartX <= ContainerWidth then
				return
			end

			Scrolling = true
			RestorePos = TextLabel.Position
			ScrollThread = task.spawn(function()
				task.wait(0.5)

				while Scrolling do
					-- Re-read each loop — text position may shift from selection changes.
					local CurTextWidth = TextLabel.TextBounds.X
					local CurContainerWidth = Container.AbsoluteSize.X
					local CurTextStartX = TextLabel.AbsolutePosition.X - Container.AbsolutePosition.X
					local Overflow = CurTextWidth + CurTextStartX - CurContainerWidth
					if Overflow <= 0 then
						task.wait(0.5)
						continue
					end

					local StartPos = TextLabel.Position
					local Duration = Overflow / 60
					local ScrolledPos = StartPos + UDim2.fromOffset(-Overflow, 0)

					TweenService
						:Create(TextLabel, TweenInfo.new(Duration, Enum.EasingStyle.Linear), { Position = ScrolledPos })
						:Play()
					task.wait(Duration + 1)
					if not Scrolling then
						break
					end

					TextLabel.Position = RestorePos or StartPos
					task.wait(0.3)
				end
			end)
		end)

		Library:Connect(Container.MouseLeave, function()
			Hovering = false
			Scrolling = false
			if ScrollThread then
				task.cancel(ScrollThread)
				ScrollThread = nil
			end
			-- Snap text back to the position it had when hover started.
			if RestorePos then
				TweenService:Create(TextLabel, TweenInfo.new(0), { Position = RestorePos }):Play()
			end
			RestorePos = nil
		end)
	end

	Library.AddToTheme = function(self, Item, Properties)
		Item = Item.Instance or Item

		local ThemeData = {
			Item = Item,
			Properties = Properties,
		}

		for Property, Value in next, ThemeData.Properties do
			if type(Value) == "string" then
				Item[Property] = self.Theme[Value]
			else
				Item[Property] = Value()
			end
		end

		TableInsert(self.ThemeItems, ThemeData)
		self.ThemeMap[Item] = ThemeData
	end

	Library.ToRich = function(self, Text, Color)
		return StringFormat(
			'<font color="rgb(%d, %d, %d)">%s</font>',
			MathFloor(Color.R * 255),
			MathFloor(Color.G * 255),
			MathFloor(Color.B * 255),
			Text
		)
	end

	Library.GetConfig = function(self)
		local Config = {}

		local Success, Result = Library:SafeCall(function()
			for Index, Value in next, Library.Flags do
				if type(Value) == "table" and Value.Key then
					Config[Index] = { Key = tostring(Value.Key), Mode = Value.Mode }
				elseif type(Value) == "table" and Value.Color then
					Config[Index] = { Color = "#" .. Value.HexValue, Alpha = Value.Alpha }
				else
					Config[Index] = Value
				end
			end
		end)

		return HttpService:JSONEncode(Config)
	end

	Library.LoadConfig = function(self, Config)
		local Decoded = HttpService:JSONDecode(Config)

		local Success, Result = Library:SafeCall(function()
			for Index, Value in next, Decoded do
				local SetFunction = Library.SetFlags[Index]

				if SetFunction then
					if type(Value) == "table" and Value.Key then
						SetFunction(Value)
					elseif type(Value) == "table" and Value.Color then
						SetFunction(Value.Color, Value.Alpha)
					else
						SetFunction(Value)
					end
				end
			end
		end)

		return Success, Result
	end

	Library.DeleteConfig = function(self, Config)
		if isfile(Library.Folders.Configs .. "/" .. Config) then
			delfile(Library.Folders.Configs .. "/" .. Config)
		end
	end

	Library.RefreshConfigsList = function(self, Element)
		local CurrentList = {}
		local List = {}

		local ConfigFolderName = StringGSub(Library.Folders.Configs, Library.Folders.Directory .. "/", "")

		local RawIdx = 0
		for Index, Value in next, listfiles(Library.Folders.Configs) do
			local FileName = StringGSub(Value, Library.Folders.Directory .. "\\" .. ConfigFolderName .. "\\", "")
			if FileName ~= "autoload.txt" then
				RawIdx = RawIdx + 1
				List[RawIdx] = FileName
			end
		end

		local IsNew = #List ~= CurrentList

		if not IsNew then
			for Index = 1, #List do
				if List[Index] ~= CurrentList[Index] then
					IsNew = true
					break
				end
			end
		else
			CurrentList = List
			Element:Refresh(CurrentList)
		end
	end

	Library.ChangeItemTheme = function(self, Item, Properties)
		Item = Item.Instance or Item

		if not self.ThemeMap[Item] then
			return
		end

		self.ThemeMap[Item].Properties = Properties
		self.ThemeMap[Item] = self.ThemeMap[Item]
	end

	Library.ChangeTheme = function(self, Theme, Color)
		self.Theme[Theme] = Color

		for Index, Item in next, self.ThemeItems do
			for Property, Value in next, Item.Properties do
				if type(Value) == "string" and Value == Theme then
					Item.Item[Property] = Color
				elseif type(Value) == "function" then
					Item.Item[Property] = Value()
				end
			end
		end

		-- Fire registered theme callbacks.
		if self._themeCallbacks then
			for Index, Fn in next, self._themeCallbacks do
				pcall(Fn)
			end
		end
	end

	Library.IsMouseOverFrame = function(self, Frame)
		Frame = Frame.Instance

		local MousePosition = Vector2New(Mouse.X, Mouse.Y)

		return MousePosition.X >= Frame.AbsolutePosition.X
			and MousePosition.X <= Frame.AbsolutePosition.X + Frame.AbsoluteSize.X
			and MousePosition.Y >= Frame.AbsolutePosition.Y
			and MousePosition.Y <= Frame.AbsolutePosition.Y + Frame.AbsoluteSize.Y
	end

	---Check if input is over a frame.
	---@param Input InputObject
	---@param Frame table
	---@return boolean
	Library.IsInputOverFrame = function(self, Input, Frame)
		Frame = Frame.Instance

		local InputPosition = Input.Position
		local MousePosition = Vector2New(InputPosition.X, InputPosition.Y)

		return MousePosition.X >= Frame.AbsolutePosition.X
			and MousePosition.X <= Frame.AbsolutePosition.X + Frame.AbsoluteSize.X
			and MousePosition.Y >= Frame.AbsolutePosition.Y
			and MousePosition.Y <= Frame.AbsolutePosition.Y + Frame.AbsoluteSize.Y
	end

	---Check if input is pointer input.
	---@param Input InputObject
	---@return boolean
	Library.IsPointerInput = function(self, Input)
		local InputType = Input.UserInputType
		return InputType == Enum.UserInputType.MouseButton1
			or InputType == Enum.UserInputType.MouseButton2
			or InputType == Enum.UserInputType.MouseButton3
			or InputType == Enum.UserInputType.Touch
	end

	---Check if input is over any open floating frame.
	---@param Input InputObject
	---@return boolean
	Library.IsInputOverOpenFrame = function(self, Input)
		for Index, Value in next, Library.OpenFrames do
			local Items = Value.Items
			if type(Items) ~= "table" then
				continue
			end

			for Name, Item in next, Items do
				local Instance = Item and Item.Instance
				if not Instance or not Instance:IsA("GuiObject") or not Instance.Visible then
					continue
				end
				if self:IsInputOverFrame(Input, Item) then
					return true
				end
			end
		end

		return false
	end

	---Check if input is over a window or its visible attached frames.
	---@param Input InputObject
	---@param Window table?
	---@return boolean
	Library.IsInputOverWindow = function(self, Input, Window)
		local Items = Window and Window.Items
		local MainFrame = Items and Items["MainFrame"]
		local MainInstance = MainFrame and MainFrame.Instance
		if not MainInstance or not MainInstance.Visible then
			return false
		end

		if self:IsInputOverFrame(Input, MainFrame) then
			return true
		end

		for Index, Child in next, MainInstance:GetChildren() do
			if not Child:IsA("GuiObject") or not Child.Visible then
				continue
			end

			local InputPosition = Input.Position
			local MousePosition = Vector2New(InputPosition.X, InputPosition.Y)
			if
				MousePosition.X >= Child.AbsolutePosition.X
				and MousePosition.X <= Child.AbsolutePosition.X + Child.AbsoluteSize.X
				and MousePosition.Y >= Child.AbsolutePosition.Y
				and MousePosition.Y <= Child.AbsolutePosition.Y + Child.AbsoluteSize.Y
			then
				return true
			end
		end

		return false
	end

	---Check if pointer keybind input should be ignored.
	---@param Input InputObject
	---@param Window table?
	---@return boolean
	Library.ShouldIgnorePointerKeybind = function(self, Input, Window)
		if not self:IsPointerInput(Input) then
			return false
		end

		if self:IsInputOverWindow(Input, Window) then
			return true
		end

		return self:IsInputOverOpenFrame(Input)
	end

	---Check if mouse is over any open dropdown's option holder.
	Library.IsMouseOverOpenDropdown = function(self)
		for Index, Frame in next, Library.OpenFrames do
			if Frame.OptionHolder and Frame.OptionHolder.Instance and Frame.OptionHolder.Instance.Visible then
				local Pos = Frame.OptionHolder.Instance.AbsolutePosition
				local Size = Frame.OptionHolder.Instance.AbsoluteSize
				local MouseX, MouseY = Mouse.X, Mouse.Y
				if MouseX >= Pos.X and MouseX <= Pos.X + Size.X and MouseY >= Pos.Y and MouseY <= Pos.Y + Size.Y then
					return true
				end
			end
		end
		return false
	end

	---Get the gui object that should be highlighted for a search entry.
	Library.GetSearchTargetInstance = function(self, Entry)
		if Entry.TargetInstance and Entry.TargetInstance:IsA("GuiObject") then
			return Entry.TargetInstance
		end

		local Source = Entry.Element or Entry.Section or Entry.Page or Entry.Tab
		local Items = Source and (Source.UiItems or Source.Items)
		if not Items then
			return nil
		end

		local function GetItem(Key)
			local Item = Items[Key]
			if Item and Item.Instance and Item.Instance:IsA("GuiObject") then
				return Item.Instance
			end
		end

		if Entry.Kind == "Page" then
			return GetItem("Inactive") or GetItem("Page")
		end

		if Entry.Kind == "Section" then
			return GetItem("TopBackground") or GetItem("Section")
		end

		if Entry.Kind == "Tab" then
			return GetItem("Button") or GetItem("TabHeader") or GetItem("TabBox")
		end

		local PreferredKeys = {
			"Button",
			"Toggle",
			"Slider",
			"Dropdown",
			"Textbox",
			"Listbox",
			"Label",
			"Frame",
			"ListHolder",
			"TabBox",
			"DepBox",
			"Divider",
			"Background",
			"SubElements",
			"RealDropdown",
			"RealSlider",
			"Input",
			"KeyButton",
			"TopBackground",
			"Inactive",
			"TabHeader",
			"Section",
			"Keybind",
		}

		for Index, Key in next, PreferredKeys do
			local Item = GetItem(Key)
			if Item then
				return Item
			end
		end

		for Index, Item in next, Items do
			if Item and Item.Instance and Item.Instance:IsA("GuiObject") then
				return Item.Instance
			end
		end

		return nil
	end

	---Create searchable entries from the current window.
	Library.CollectSearchEntries = function(self, Window, Query)
		local QueryText = StringLower(tostring(Query or ""))
		local Results = {}
		local SeenTargets = {}

		if QueryText == "" then
			return Results
		end

		local function AddTerm(Terms, Value)
			if Value == nil then
				return
			end

			local ValueType = type(Value)
			if ValueType ~= "string" and ValueType ~= "number" and ValueType ~= "boolean" then
				return
			end

			Value = tostring(Value)
			if Value == "" then
				return
			end

			Terms[#Terms + 1] = Value
		end

		local function AddTermsFromGuiObject(Terms, Object)
			if not Object or not Object:IsA("GuiObject") then
				return
			end

			local Objects = Object:GetDescendants()
			Objects[#Objects + 1] = Object

			for Index, Descendant in next, Objects do
				if Descendant:IsA("TextLabel") or Descendant:IsA("TextButton") or Descendant:IsA("TextBox") then
					AddTerm(Terms, Descendant.Text)

					if Descendant:IsA("TextBox") then
						AddTerm(Terms, Descendant.PlaceholderText)
					end
				end
			end
		end

		local function AddTermsFromUiItems(Terms, Items)
			if not Items then
				return
			end

			for Index, Item in next, Items do
				if type(Item) == "table" and Item.Instance then
					AddTermsFromGuiObject(Terms, Item.Instance)
				elseif typeof and typeof(Item) == "Instance" and Item:IsA("GuiObject") then
					AddTermsFromGuiObject(Terms, Item)
				end
			end
		end

		local function AddTermsFromDataList(Terms, List)
			if type(List) ~= "table" then
				return
			end

			for Key, Value in next, List do
				AddTerm(Terms, Key)

				if type(Value) == "table" then
					AddTerm(Terms, Value.Name)
					AddTerm(Terms, Value.Display)
					AddTerm(Terms, Value.Key)
				else
					AddTerm(Terms, Value)
				end
			end
		end

		local function GetElementTerms(Element)
			local Terms = {}
			local IsContainerElement = Element.Tabs or Element.Elements

			AddTerm(Terms, Element.Name)
			AddTerm(Terms, Element.Flag)
			AddTerm(Terms, Element.Placeholder)
			AddTerm(Terms, Element.Value)
			AddTerm(Terms, Element.Default)
			AddTerm(Terms, Element.Suffix)
			AddTerm(Terms, Element.Mode)
			AddTerm(Terms, Element.Description)

			if not IsContainerElement then
				AddTermsFromUiItems(Terms, Element.UiItems or Element.Items)
			end

			if Element.UiItems and Element.Items then
				AddTermsFromDataList(Terms, Element.Items)
			end

			AddTermsFromDataList(Terms, Element.Options)
			AddTermsFromDataList(Terms, Element.ItemData)

			if Element.Tabs then
				for TabName in next, Element.Tabs do
					AddTerm(Terms, TabName)
				end
			end

			return Terms
		end

		local function AddEntry(Entry)
			Entry.Name = tostring(Entry.Name or Entry.Kind or "Item")

			Entry.SearchText = StringLower(
				StringFormat("%s %s %s %s", Entry.Kind or "", Entry.Name or "", Entry.Path or "", Entry.Terms or "")
			)

			if not StringFind(Entry.SearchText, QueryText, 1, true) then
				return
			end

			Entry.TargetInstance = Library:GetSearchTargetInstance(Entry)
			if not Entry.TargetInstance then
				return
			end

			if SeenTargets[Entry.TargetInstance] then
				return
			end

			SeenTargets[Entry.TargetInstance] = true
			Results[#Results + 1] = Entry
		end

		local function WalkElements(Elements, Page, RootSection, Path, TabBox, Tab)
			for Index, Element in next, Elements do
				local EntryPath = Path
				local Terms = GetElementTerms(Element)
				local ElementName = Element.Name or Terms[1] or Element.Flag or "Control"

				AddEntry({
					Kind = "Control",
					Name = ElementName,
					Page = Page,
					Section = RootSection,
					Element = Element,
					Path = EntryPath .. " / " .. ElementName,
					Terms = TableConcat(Terms, " "),
					TabBox = TabBox,
					Tab = Tab,
				})

				if Element.Tabs then
					for TabName, TabRef in next, Element.Tabs do
						local TabPath = EntryPath .. " / " .. TabName
						AddEntry({
							Kind = "Tab",
							Name = TabName,
							Page = Page,
							Section = RootSection,
							TabBox = Element,
							Tab = TabRef,
							Path = TabPath,
						})

						if TabRef.Elements then
							WalkElements(TabRef.Elements, Page, RootSection, TabPath, Element, TabRef)
						end
					end
				end

				if Element.Elements then
					WalkElements(Element.Elements, Page, RootSection, EntryPath, TabBox, Tab)
				end
			end
		end

		for Index, Page in next, Window.Pages do
			AddEntry({
				Kind = "Page",
				Name = Page.Name,
				Page = Page,
				Path = Page.Name,
			})

			for Index, Section in next, Page.Sections do
				local SectionPath = Page.Name .. " / " .. Section.Name
				AddEntry({
					Kind = "Section",
					Name = Section.Name,
					Page = Page,
					Section = Section,
					Path = SectionPath,
				})

				WalkElements(Section.Elements, Page, Section, SectionPath)
			end
		end

		return Results
	end

	---Flash a search result target with the accent color.
	Library.FlashSearchEntry = function(self, Entry)
		local FlashHoldTime = 0.25
		local FlashFadeTime = 1.1

		local Target = self:GetSearchTargetInstance(Entry)
		if not Target or not Target.Parent then
			return
		end

		local Targets = {}
		local Seen = {}

		local function AddTarget(Item)
			if not Item or not Item:IsA("GuiObject") or Seen[Item] then
				return
			end

			Seen[Item] = true
			Targets[#Targets + 1] = Item
		end

		AddTarget(Target)

		for Index, FlashTarget in next, Targets do
			local Flash = InstanceNew("Frame")
			Flash.Name = "\0"
			Flash.BackgroundColor3 = Library.Theme.Accent
			Flash.BackgroundTransparency = 0
			Flash.BorderSizePixel = 0
			Flash.Size = UDim2New(1, 0, 1, 0)
			Flash.Position = UDim2New(0, 0, 0, 0)
			Flash.ZIndex = FlashTarget.ZIndex + 35
			Flash.Parent = FlashTarget

			Instances:Create("UICorner", {
				Parent = Flash,
				Name = "\0",
				CornerRadius = UDimNew(0, 6),
			})

			task.delay(FlashHoldTime, function()
				if not Flash then
					return
				end

				TweenService
					:Create(Flash, TweenInfo.new(FlashFadeTime, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
						BackgroundTransparency = 1,
					})
					:Play()
			end)

			task.delay(FlashHoldTime + FlashFadeTime + 0.05, function()
				if Flash then
					Flash:Destroy()
				end
			end)
		end
	end

	---Activate a search result.
	Library.ActivateSearchEntry = function(self, Entry)
		local Page = Entry.Page
		if Page and Page.Window then
			for Index, PageRef in next, Page.Window.Pages do
				if PageRef == Page then
					if not PageRef.Active then
						PageRef:Turn(true)
					end
				elseif PageRef.Active then
					PageRef:Turn(false)
				end
			end
		end

		local function ShouldExpandCollapsedSection()
			if not Entry.Section or not Entry.Section.Collapsible or Entry.Section.IsActive then
				return false
			end

			local SectionItems = Entry.Section.Items or Entry.Section.UiItems
			local SectionContent = SectionItems and SectionItems["Content"] and SectionItems["Content"].Instance
			local Target = self:GetSearchTargetInstance(Entry)

			return Target and SectionContent and Target:IsDescendantOf(SectionContent)
		end

		if ShouldExpandCollapsedSection() then
			Entry.Section:ToggleBackground(true)
			task.wait(0.45)
		end

		if Entry.TabBox and Entry.Tab then
			Entry.TabBox:SwitchTab(Entry.Tab.Name)
			task.wait(0.05)
		end

		task.wait(0.1)

		local Target = self:GetSearchTargetInstance(Entry)
		if not Target then
			return
		end

		local ScrollFrame = Target:FindFirstAncestorWhichIsA("ScrollingFrame")
		if ScrollFrame then
			local TargetY = Target.AbsolutePosition.Y
				- ScrollFrame.AbsolutePosition.Y
				+ ScrollFrame.CanvasPosition.Y
				- 20
			TargetY = MathClamp(TargetY, 0, math.max(0, ScrollFrame.AbsoluteCanvasSize.Y - ScrollFrame.AbsoluteSize.Y))
			TweenService:Create(ScrollFrame, TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
				CanvasPosition = Vector2New(0, TargetY),
			}):Play()
			task.wait(0.25)
		end

		self:FlashSearchEntry(Entry)
	end

	Library.Lerp = function(self, Start, Finish, Time)
		return Start + (Finish - Start) * Time
	end

	Library.CompareVectors = function(self, PointA, PointB)
		return (PointA.X < PointB.X) or (PointA.Y < PointB.Y)
	end

	Library.IsClipped = function(self, Object, Column)
		local Parent = Column

		local BoundryTop = Parent.AbsolutePosition
		local BoundryBottom = BoundryTop + Parent.AbsoluteSize

		local Top = Object.AbsolutePosition
		local Bottom = Top + Object.AbsoluteSize

		return Library:CompareVectors(Top, BoundryTop) or Library:CompareVectors(BoundryBottom, Bottom)
	end

	Library.GetCalculatedRayPosition = function(self, Position, Normal, Origin, Direction)
		local N = Normal
		local D = Direction
		local V = Origin - Position

		local Number = (N.x * V.x) + (N.y * V.y) + (N.z * V.z)
		local Den = (N.x * D.x) + (N.y * D.y) + (N.z * D.z)
		local A = -Number / Den

		return Origin + (A * Direction)
	end

	Library.UpdateText = function(self)
		for Index, Value in next, self.UnusedHolder.Instance:GetDescendants() do
			if Value:IsA("TextLabel") or Value:IsA("TextButton") or Value:IsA("TextBox") then
				Value.FontFace = Library.Font
			end
		end

		for Index, Value in next, self.Holder.Instance:GetDescendants() do
			if Value:IsA("TextLabel") or Value:IsA("TextButton") or Value:IsA("TextBox") then
				Value.FontFace = Library.Font
			end
		end
	end

	Library.MakeBlurred = function(self, Item, Window)
		Item = Item.Instance
		local BlurItem = Item

		local Part = Instances:Create("Part", {
			Material = Enum.Material.Glass,
			Transparency = 1,
			Reflectance = 0,
			CastShadow = false,
			Anchored = true,
			CanCollide = false,
			CanQuery = false,
			CollisionGroup = " ",
			Size = Vector3New(1, 1, 1) * 0.01,
			Color = FromRGB(0, 0, 0),
			Parent = Camera,
		})

		local BlockMesh = Instances:Create("BlockMesh", { Parent = Part.Instance })

		local DepthOfField = Instances:Create("DepthOfFieldEffect", {
			Parent = Lighting,
			Enabled = true,
			FarIntensity = 0,
			FocusDistance = 0,
			InFocusRadius = 1000,
			NearIntensity = 0,
			Name = "",
		})

		Library:Connect(RunService.RenderStepped, function()
			if Window.IsOpen then
				if Item.Visible then
					DepthOfField:Tween(nil, { NearIntensity = 1 })
					Part:Tween(nil, { Transparency = 0.97 })
					Part:Tween(nil, { Size = Vector3New(1, 1, 1) * 0.01 })

					-- Inset by 2px to avoid DoF overflow past UI corner radius.
					local Inset = Vector2New(2, 2)
					local Corner0 = BlurItem.AbsolutePosition + Inset
					local Corner1 = Corner0 + BlurItem.AbsoluteSize - Inset - Inset

					local Ray0 = Camera.ScreenPointToRay(Camera, Corner0.X, Corner0.Y, 1)
					local Ray1 = Camera.ScreenPointToRay(Camera, Corner1.X, Corner1.Y, 1)

					local Origin = Camera.CFrame.Position + Camera.CFrame.LookVector * (0.05 - Camera.NearPlaneZ)

					local Normal = Camera.CFrame.LookVector

					local Position0 = Library:GetCalculatedRayPosition(Origin, Normal, Ray0.Origin, Ray0.Direction)
					local Position1 = Library:GetCalculatedRayPosition(Origin, Normal, Ray1.Origin, Ray1.Direction)

					Position0 = Camera.CFrame:PointToObjectSpace(Position0)
					Position1 = Camera.CFrame:PointToObjectSpace(Position1)

					local Size = Position1 - Position0
					local Center = (Position0 + Position1) / 2

					BlockMesh.Instance.Offset = Center
					BlockMesh.Instance.Scale = Size / 0.0101

					Part.Instance.CFrame = Camera.CFrame
				else
					DepthOfField:Tween(nil, { NearIntensity = 0 })
					BlockMesh.Instance.Offset = Vector3New(0, 0, 0)
					BlockMesh.Instance.Scale = Vector3New(0, 0, 0)
				end
			else
				DepthOfField:Tween(nil, { NearIntensity = 0 })
				BlockMesh.Instance.Offset = Vector3New(0, 0, 0)
				BlockMesh.Instance.Scale = Vector3New(0, 0, 0)
			end
		end)
	end

	Library.EscapePattern = function(self, String)
		local ShouldEscape = false

		if string.match(String, "[%(%)%.%%%+%-%*%?%[%]%^%$]") then
			ShouldEscape = true
		end

		if ShouldEscape then
			return StringGSub(String, "[%(%)%.%%%+%-%*%?%[%]%^%$]", "%%%1")
		end

		return String
	end

