					PaddingBottom = UDimNew(0, 5),
				})

				Items["HEXInput"] = Instances:Create("TextBox", {
					Parent = Items["ColorpickerWindow"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(240, 240, 240),
					BorderColor3 = FromRGB(0, 0, 0),
					ClearTextOnFocus = false,
					Text = "#7ca3ff",
					AnchorPoint = Vector2New(1, 1),
					Size = UDim2New(0, 140, 0, 20),
					TextTransparency = 0.5,
					PlaceholderColor3 = FromRGB(185, 185, 185),
					Position = UDim2New(1, -8, 1, -8),
					TextXAlignment = Enum.TextXAlignment.Left,
					BorderSizePixel = 0,
					TextSize = 14,
					BackgroundColor3 = FromRGB(30, 29, 31),
				})
				Items["HEXInput"]:AddToTheme({ BackgroundColor3 = "Outline" })

				Instances:Create("UIPadding", {
					Parent = Items["HEXInput"].Instance,
					Name = "\0",
					PaddingLeft = UDimNew(0, 5),
				})

				Items["HexLabel"] = Instances:Create("TextLabel", {
					Parent = Items["ColorpickerWindow"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(240, 240, 240),
					BorderColor3 = FromRGB(0, 0, 0),
					Text = "Custom:",
					TextTransparency = 0.5,
					AnchorPoint = Vector2New(0, 1),
					Size = UDim2New(0, 40, 0, 20),
					Position = UDim2New(0, 10, 1, -8),
					BorderSizePixel = 0,
					TextSize = 14,
					BackgroundTransparency = 1,
					BackgroundColor3 = FromRGB(30, 29, 31),
				})
				Items["HexLabel"]:AddToTheme({ TextColor3 = "Text" })

				Instances:Create("UICorner", {
					Parent = Items["HEXInput"].Instance,
					Name = "\0",
					CornerRadius = UDimNew(0, 4),
				})
			end

			function Colorpicker:Get()
				return Colorpicker.Color, Colorpicker.Alpha
			end

			function Colorpicker:Update(IsFromAlpha)
				local Hue, Saturation, Value = Colorpicker.Hue, Colorpicker.Saturation, Colorpicker.Value
				Colorpicker.Color = FromHSV(Hue, Saturation, Value)
				Colorpicker.HexValue = Colorpicker.Color:ToHex()

				Library.Flags[Colorpicker.Flag] = {
					Alpha = Colorpicker.Alpha,
					Color = Colorpicker.Color,
					HexValue = Colorpicker.HexValue,
					Transparency = 1 - Colorpicker.Alpha,
				}

				Items["Color"]:Tween(nil, { BackgroundColor3 = Colorpicker.Color })
				Items["Palette"]:Tween(nil, { BackgroundColor3 = FromHSV(Hue, 1, 1) })
				Items["Text"].Instance.Text = ("#" .. Colorpicker.HexValue):upper()
				Items["HEXInput"].Instance.Text = "#" .. Colorpicker.HexValue

				if not IsFromAlpha then
					Items["Alpha"]:Tween(nil, { BackgroundColor3 = Colorpicker.Color })
				end

				if Data.Callback then
					Library:SafeCall(Data.Callback, Colorpicker.Color, Colorpicker.Alpha)
				end
			end

			local SlidingPalette = false
			local PaletteChanged

			function Colorpicker:SlidePalette(Input)
				if not Input or not SlidingPalette then
					return
				end

				local ValueX = MathClamp(
					1
						- (Input.Position.X - Items["Palette"].Instance.AbsolutePosition.X)
							/ Items["Palette"].Instance.AbsoluteSize.X,
					0,
					1
				)
				local ValueY = MathClamp(
					1
						- (Input.Position.Y - Items["Palette"].Instance.AbsolutePosition.Y)
							/ Items["Palette"].Instance.AbsoluteSize.Y,
					0,
					1
				)

				Colorpicker.Saturation = ValueX
				Colorpicker.Value = ValueY

				local SlideX = MathClamp(
					(Input.Position.X - Items["Palette"].Instance.AbsolutePosition.X)
						/ Items["Palette"].Instance.AbsoluteSize.X,
					0,
					0.955
				)
				local SlideY = MathClamp(
					(Input.Position.Y - Items["Palette"].Instance.AbsolutePosition.Y)
						/ Items["Palette"].Instance.AbsoluteSize.Y,
					0,
					0.955
				)

				Items["PaletteDragger"]:Tween(
					TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(SlideX, 0, SlideY, 0) }
				)
				Colorpicker:Update()
			end

			local SlidingHue = false
			local HueChanged

			function Colorpicker:SlideHue(Input)
				if not Input or not SlidingHue then
					return
				end

				local ValueX = MathClamp(
					(Input.Position.X - Items["Hue"].Instance.AbsolutePosition.X) / Items["Hue"].Instance.AbsoluteSize.X,
					0,
					1
				)

				Colorpicker.Hue = ValueX

				local SlideX = MathClamp(
					(Input.Position.X - Items["Hue"].Instance.AbsolutePosition.X) / Items["Hue"].Instance.AbsoluteSize.X,
					0,
					0.955
				)

				Items["HueDragger"]:Tween(
					TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(SlideX, 0, 0.5, 0) }
				)
				Colorpicker:Update()
			end

			local SlidingAlpha = false
			local AlphaChanged

			function Colorpicker:SlideAlpha(Input)
				if not Input or not SlidingAlpha then
					return
				end

				local ValueX = MathClamp(
					(Input.Position.X - Items["Alpha"].Instance.AbsolutePosition.X)
						/ Items["Alpha"].Instance.AbsoluteSize.X,
					0,
					1
				)

				Colorpicker.Alpha = ValueX

				local SlideX = MathClamp(
					(Input.Position.X - Items["Alpha"].Instance.AbsolutePosition.X)
						/ Items["Alpha"].Instance.AbsoluteSize.X,
					0,
					0.955
				)

				Items["AlphaDragger"]:Tween(
					TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(SlideX, 0, 0.5, 0) }
				)
				Colorpicker:Update(true)
			end

			local Debounce = false
			local RenderStepped

			function Colorpicker:SetOpen(Bool)
				if Debounce then
					return
				end

				Colorpicker.IsOpen = Bool

				Debounce = true

				if Colorpicker.IsOpen then
					Items["ColorpickerWindow"].Instance.Visible = true
					Items["ColorpickerWindow"].Instance.Parent = Library.OverlayHolder.Instance

					RenderStepped = RunService.RenderStepped:Connect(function()
						local BtnPos = Items["ColorpickerButton"].Instance.AbsolutePosition
						local WinSize = Items["ColorpickerWindow"].Instance.AbsoluteSize

						-- Always show above.
						Items["ColorpickerWindow"].Instance.Position =
							UDim2New(0, BtnPos.X, 0, BtnPos.Y - WinSize.Y - 5)
					end)

					if Data.Section.IsSettings ~= true then
						for Index, Value in next, Library.OpenFrames do
							if Value ~= Colorpicker then
								pcall(Value.SetOpen, Value, false)
							end
						end
					end

					Library.OpenFrames[Colorpicker] = Colorpicker
				else
					if not Data.Section.IsSettings then
						if Library.OpenFrames[Colorpicker] then
							Library.OpenFrames[Colorpicker] = nil
						end
					end

					if RenderStepped then
						RenderStepped:Disconnect()
						RenderStepped = nil
					end
				end

				local Descendants = Items["ColorpickerWindow"].Instance:GetDescendants()
				TableInsert(Descendants, Items["ColorpickerWindow"].Instance)

				local NewTween

				for Index, Value in next, Descendants do
					local TransparencyProperty = Tween:GetProperty(Value)

					if TransparencyProperty then
						if not Value.ClassName:find("UI") then
							Value.ZIndex = (Colorpicker.IsOpen and Data.Section.IsSettings and 9)
								or (Colorpicker.IsOpen and not Data.Section.IsSettings and 3)
								or 1
						end

						if type(TransparencyProperty) == "table" then
							for Index, Property in next, TransparencyProperty do
								NewTween = Tween:FadeItem(Value, Property, Bool, Library.FadeSpeed)
							end
						else
							NewTween = Tween:FadeItem(Value, TransparencyProperty, Bool, Library.FadeSpeed)
						end
					end
				end

				NewTween.Tween.Completed:Connect(function()
					Debounce = false
					Items["ColorpickerWindow"].Instance.Visible = Colorpicker.IsOpen
					task.wait(0.2)
					Items["ColorpickerWindow"].Instance.Parent = not Colorpicker.IsOpen
							and Library.UnusedHolder.Instance
						or Library.OverlayHolder.Instance
				end)
			end

			function Colorpicker:Set(Color, Alpha)
				if type(Color) == "table" then
					Color = FromRGB(Color[1], Color[2], Color[3])
					Alpha = Color[4]
				elseif type(Color) == "string" then
					Color = FromHex(Color)
				end

				Colorpicker.Hue, Colorpicker.Saturation, Colorpicker.Value = Color:ToHSV()
				Colorpicker.Alpha = Alpha or 0

				local PaletteValueX = MathClamp(1 - Colorpicker.Saturation, 0, 0.955)
				local PaletteValueY = MathClamp(1 - Colorpicker.Value, 0, 0.955)

				local AlphaPositionX = MathClamp(Colorpicker.Alpha, 0, 0.955)

				local HuePositionX = MathClamp(Colorpicker.Hue, 0, 0.955)

				Items["PaletteDragger"]:Tween(
					TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(PaletteValueX, 0, PaletteValueY, 0) }
				)
				Items["HueDragger"]:Tween(
					TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(HuePositionX, 0, 0.5, 0) }
				)
				Items["AlphaDragger"]:Tween(
					TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
					{ Position = UDim2New(AlphaPositionX, 0, 0.5, 0) }
				)
				Colorpicker:Update()
			end

			Items["ColorpickerButton"]:Connect("MouseButton1Down", function()
				Colorpicker:SetOpen(not Colorpicker.IsOpen)
			end)

			-- Make palette icon clickable.
			if Items["PaletteIcon"] then
				Items["PaletteIcon"].Instance.InputBegan:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 then
						Colorpicker:SetOpen(not Colorpicker.IsOpen)
					end
				end)
			end

			-- Make the entire SubElements row clickable.
			if Data.Parent and Data.Parent.Instance then
				Data.Parent.Instance.InputBegan:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 then
						Colorpicker:SetOpen(not Colorpicker.IsOpen)
					end
				end)
			end

			Items["Palette"]:Connect("InputBegan", function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseButton1
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					SlidingPalette = true

					Colorpicker:SlidePalette(Input)

					if PaletteChanged then
						return
					end

					PaletteChanged = Input.Changed:Connect(function()
						if Input.UserInputState == Enum.UserInputState.End then
							SlidingPalette = false

							PaletteChanged:Disconnect()
							PaletteChanged = nil
						end
					end)
				end
			end)

			Items["HueInline"]:Connect("InputBegan", function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseButton1
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					SlidingHue = true

					Colorpicker:SlideHue(Input)

					if HueChanged then
						return
					end

					HueChanged = Input.Changed:Connect(function()
						if Input.UserInputState == Enum.UserInputState.End then
							SlidingHue = false

							HueChanged:Disconnect()
							HueChanged = nil
						end
					end)
				end
			end)

			Items["Alpha"]:Connect("InputBegan", function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseButton1
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					SlidingAlpha = true

					Colorpicker:SlideAlpha(Input)

					if AlphaChanged then
						return
					end

					AlphaChanged = Input.Changed:Connect(function()
						if Input.UserInputState == Enum.UserInputState.End then
							SlidingAlpha = false

							AlphaChanged:Disconnect()
							AlphaChanged = nil
						end
					end)
				end
			end)

			function AddColor(Color)
				--if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
				local SaveIndex = #Colorpicker.SavedColors + 1

				local SavedColor = Instances:Create("TextButton", {
					Parent = Items["SavedColors"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(0, 0, 0),
					BorderColor3 = FromRGB(0, 0, 0),
					Text = "",
					AutoButtonColor = false,
					Size = UDim2New(0, 200, 0, 50),
					BorderSizePixel = 0,
					TextSize = 14,
					BackgroundTransparency = 1,
					ZIndex = 4,
					BackgroundColor3 = Color,
				})

				Instances:Create("UICorner", {
					Parent = SavedColor.Instance,
					Name = "\0",
					CornerRadius = UDimNew(0, 6),
				})

				local UIStroke = Instances:Create("UIStroke", {
					Parent = SavedColor.Instance,
					Name = "\0",
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
					Color = FromRGB(255, 255, 255),
					Thickness = 1.5,
					Transparency = 1,
				})

				SavedColor:OnHover(function()
					UIStroke:Tween(nil, { Transparency = 0 })
				end)

				SavedColor:OnHoverLeave(function()
					UIStroke:Tween(nil, { Transparency = 1 })
				end)

				Colorpicker.SavedColors[SaveIndex] = {
					Color = Color,
					Alpha = Colorpicker.Alpha,
				}

				SavedColor:Connect("MouseButton1Down", function()
					local NewColorData = Colorpicker.SavedColors[SaveIndex]
					Colorpicker:Set(NewColorData.Color, NewColorData.Alpha)
				end)

				SavedColor:Tween(nil, { BackgroundTransparency = 0 })
				--end
			end

			local Colors = {
				["Orange"] = FromRGB(245, 114, 66),
				["Pink"] = FromRGB(245, 66, 191),
				["Purple"] = FromRGB(124, 54, 245),
				["Pink 2"] = FromRGB(202, 110, 255),
				["Pink 3"] = FromRGB(250, 142, 239),
				["Yellow"] = FromRGB(214, 206, 92),
				["Orange 2"] = FromRGB(255, 93, 48),
				["Orange 3"] = FromRGB(255, 169, 56),
				["Green"] = FromRGB(0, 171, 0),
				["Blue"] = FromRGB(0, 116, 224),
				["Maroon"] = FromRGB(120, 0, 76),
				["Whiteish Pink"] = FromRGB(255, 194, 245),
				["White"] = FromRGB(255, 255, 255),
				["Red"] = FromRGB(255, 0, 0),
				["Sky Blue"] = FromRGB(171, 209, 255),
			}

			AddColor(Colors["Orange"])
			AddColor(Colors["Pink"])
			AddColor(Colors["Purple"])
			AddColor(Colors["Pink 2"])
			AddColor(Colors["Pink 3"])
			AddColor(Colors["Yellow"])
			AddColor(Colors["Orange 2"])
			AddColor(Colors["Orange 3"])
			AddColor(Colors["Green"])
			AddColor(Colors["Blue"])
			AddColor(Colors["Maroon"])
			AddColor(Colors["Whiteish Pink"]) -- had to do it in order
			AddColor(Colors["White"])
			AddColor(Colors["Red"])
			AddColor(Colors["Sky Blue"])

			Items["HEXInput"]:Connect("FocusLost", function()
				Colorpicker:Set(tostring(Items["HEXInput"].Instance.Text), Colorpicker.Alpha)
			end)

			Library:Connect(UserInputService.InputChanged, function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseMovement
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					if SlidingPalette then
						Colorpicker:SlidePalette(Input)
					end

					if SlidingHue then
						Colorpicker:SlideHue(Input)
					end

					if SlidingAlpha then
						Colorpicker:SlideAlpha(Input)
					end
				end
			end)

			Library:Connect(UserInputService.InputBegan, function(Input)
				if
					Input.UserInputType == Enum.UserInputType.MouseButton1
					or Input.UserInputType == Enum.UserInputType.Touch
				then
					if not Colorpicker.IsOpen then
						return
					end

					if
						Library:IsMouseOverFrame(Items["ColorpickerWindow"])
						or Library:IsMouseOverFrame(Items["PaletteIcon"]) and not Data.Section.IsSettings
					then
						return
					end

					Colorpicker:SetOpen(false)
				end
			end)

			if Data.Default then
				Colorpicker:Set(Data.Default, Data.Alpha)
			end

			Library.SetFlags[Colorpicker.Flag] = function(Value, Alpha)
				Colorpicker:Set(Value, Alpha)
			end

			return Colorpicker, Items
		end

		Library.KeybindList = function(self, Title)
