				})

				Instances:Create("UIGradient", {
					Parent = Items["Icon"].Instance,
					Name = "\0",
					Rotation = -115,
					Color = RGBSequence({
						RGBSequenceKeypoint(0, FromRGB(255, 255, 255)),
						RGBSequenceKeypoint(1, FromRGB(143, 143, 143)),
					}),
				}):AddToTheme({
					Color = function()
						return RGBSequence({
							RGBSequenceKeypoint(0, Library.Theme.Accent),
							RGBSequenceKeypoint(1, Library.Theme.AccentGradient),
						})
					end,
				})

				Items["Title"] = Instances:Create("TextLabel", {
					Parent = Items["Watermark"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(248, 248, 248),
					BorderColor3 = FromRGB(0, 0, 0),
					Text = Title or "Watermark",
					AutomaticSize = Enum.AutomaticSize.X,
					AnchorPoint = Vector2New(0, 0.5),
					Size = UDim2New(0, 0, 0, 15),
					BackgroundTransparency = 1,
					Position = UDim2New(0, 22, 0.5, 0),
					BorderSizePixel = 0,
					ZIndex = 11,
					TextSize = 14,
					BackgroundColor3 = FromRGB(255, 255, 255),
				})
				Items["Title"]:AddToTheme({ TextColor3 = "Text" })
			end

			function Watermark:SetText(Text)
				Items["Title"].Instance.Text = Text
			end

			function Watermark:SetVisibility(Bool)
				Items["Watermark"].Instance.Visible = Bool
			end

			function Watermark:PositionAboveWindow(Window)
				-- Position watermark centered above the main frame only, 10px gap.
				Items["Watermark"].Instance.Visible = false
				task.defer(function()
					task.wait(0.8)
					if not Window.Items then
						return
					end
					local MainFrame = Window.Items["MainFrame"]
					if not MainFrame then
						return
					end

					local MfPos = MainFrame.Instance.AbsolutePosition
					local MfSize = MainFrame.Instance.AbsoluteSize

					local CenterX = MfPos.X + MfSize.X / 2
					local TopY = MfPos.Y + 50

					Items["Watermark"].Instance.AnchorPoint = Vector2New(0.5, 1)
					Items["Watermark"].Instance.Position = UDim2New(0, CenterX, 0, TopY)
					if getgenv().WrathSilentMode then
						return
					end
					Items["Watermark"].Instance.Visible = true
				end)
			end

			return Watermark
		end

		Library.Notification = function(self, Data)
			if getgenv().WrathSilentMode then
				return
			end

			Data.Duration = Data.Duration or 5
			local Sticky = Data.Sticky == true or Data.Duration == math.huge or Data.Duration <= 0
			local Items = {}
			do
				Items["Notification"] = Instances:Create("Frame", {
					Parent = Library.NotifHolder.Instance,
					Name = "\0",
					BackgroundTransparency = 0.35,
					BorderColor3 = FromRGB(0, 0, 0),
					BorderSizePixel = 0,
					AutomaticSize = Enum.AutomaticSize.XY,
					BackgroundColor3 = FromRGB(27, 25, 29),
				})

				Items["Title"] = Instances:Create("TextLabel", {
					Parent = Items["Notification"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(255, 255, 255),
					BorderColor3 = FromRGB(0, 0, 0),
					Text = Data.Title,
					BackgroundTransparency = 1,
					Size = UDim2New(0, 0, 0, 15),
					BorderSizePixel = 0,
					AutomaticSize = Enum.AutomaticSize.XY,
					TextSize = 14,
					BackgroundColor3 = FromRGB(255, 255, 255),
				})
				Items["Title"]:AddToTheme({ TextColor3 = "Text" })

				Instances:Create("UIPadding", {
					Parent = Items["Notification"].Instance,
					Name = "\0",
					PaddingTop = UDimNew(0, 8),
					PaddingBottom = UDimNew(0, 8),
					PaddingRight = UDimNew(0, 8),
					PaddingLeft = UDimNew(0, 8),
				})

				Instances:Create("UICorner", {
					Parent = Items["Notification"].Instance,
					Name = "\0",
					CornerRadius = UDimNew(0, 5),
				})

				Items["Description"] = Instances:Create("TextLabel", {
					Parent = Items["Notification"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(255, 255, 255),
					TextTransparency = 0.3,
					Text = Data.Description,
					Size = UDim2New(0, 0, 0, 15),
					BorderSizePixel = 0,
					BackgroundTransparency = 1,
					Position = UDim2New(0, 0, 0, 20),
					BorderColor3 = FromRGB(0, 0, 0),
					AutomaticSize = Enum.AutomaticSize.XY,
					TextSize = 14,
					BackgroundColor3 = FromRGB(255, 255, 255),
				})
				Items["Description"]:AddToTheme({ TextColor3 = "Text" })

				Items["Accent"] = Instances:Create("Frame", {
					Parent = Items["Notification"].Instance,
					Name = "\0",
					Position = UDim2New(
						0,
						0,
						0,
						Items["Description"].Instance.AbsoluteSize.Y + Items["Title"].Instance.AbsoluteSize.Y + 12
					),
					BorderColor3 = FromRGB(0, 0, 0),
					Size = UDim2New(0, 0, 0, 6),
					BorderSizePixel = 0,
					BackgroundColor3 = FromRGB(255, 255, 255),
				})

				Instances:Create("UICorner", {
					Parent = Items["Accent"].Instance,
					Name = "\0",
					CornerRadius = UDimNew(1, 0),
				})

				Instances:Create("UIGradient", {
					Parent = Items["Accent"].Instance,
					Name = "\0",
					Color = RGBSequence({
						RGBSequenceKeypoint(0, FromRGB(255, 255, 255)),
						RGBSequenceKeypoint(1, FromRGB(143, 143, 143)),
					}),
				}):AddToTheme({
					Color = function()
						return RGBSequence({
							RGBSequenceKeypoint(0, Library.Theme.Accent),
							RGBSequenceKeypoint(1, Library.Theme.AccentGradient),
						})
					end,
				})

				if Data.Icon then
					Items["Icon"] = Instances:Create("ImageLabel", {
						Parent = Items["Notification"].Instance,
						Name = "\0",
						ImageColor3 = FromRGB(255, 255, 255),
						BorderColor3 = FromRGB(0, 0, 0),
						AnchorPoint = Vector2New(1, 0),
						Image = (StringFind(tostring(Data.Icon), "rbxasset") and Data.Icon)
							or ("rbxassetid://" .. tostring(Data.Icon)),
						BackgroundTransparency = 1,
						Position = UDim2New(1, 0, 0, 0),
						Size = UDim2New(0, 16, 0, 16),
						BorderSizePixel = 0,
						BackgroundColor3 = FromRGB(255, 255, 255),
					})

					if not Data.IconColor then
						Instances:Create("UIGradient", {
							Parent = Items["Icon"].Instance,
							Name = "\0",
							Rotation = -115,
							Color = RGBSequence({
								RGBSequenceKeypoint(0, FromRGB(255, 255, 255)),
								RGBSequenceKeypoint(1, FromRGB(143, 143, 143)),
							}),
						}):AddToTheme({
							Color = function()
								return RGBSequence({
									RGBSequenceKeypoint(0, Library.Theme.Accent),
									RGBSequenceKeypoint(1, Library.Theme.AccentGradient),
								})
							end,
						})
					else
						Instances:Create("UIGradient", {
							Parent = Items["Icon"].Instance,
							Name = "\0",
							Rotation = -115,
							Color = RGBSequence({
								RGBSequenceKeypoint(0, Data.IconColor.Start),
								RGBSequenceKeypoint(1, Data.IconColor.End),
							}),
						})
					end
				end
			end

			for Index, Value in next, Items do
				if Value.Instance:IsA("Frame") then
					Value.Instance.BackgroundTransparency = 1
				elseif Value.Instance:IsA("TextLabel") then
					Value.Instance.TextTransparency = 1
				elseif Value.Instance:IsA("ImageLabel") then
					Value.Instance.ImageTransparency = 1
				end
			end

			Items["Notification"].Instance.ClipsDescendants = true
			RunService.RenderStepped:Wait()

			local Size = Items["Notification"].Instance.AbsoluteSize + Vector2New(2, 0)
			Items["Notification"].Instance.Size = UDim2New(0, 0, 0, 0)

			task.wait(0.2)

			Items["Notification"].Instance.AutomaticSize = Enum.AutomaticSize.Y

			local Dismissed = false
			local function DismissNotification()
				if Dismissed then
					return
				end
				Dismissed = true

				-- Fade out text and icons first.
				for Index, Value in next, Items do
					if Value.Instance:IsA("TextLabel") then
						Value:Tween(
							TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
							{ TextTransparency = 1 }
						)
					elseif Value.Instance:IsA("ImageLabel") then
						Value:Tween(
							TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
							{ ImageTransparency = 1 }
						)
					end
				end

				task.wait(0.2)

				-- Collapse the entire frame.
				Items["Notification"]:Tween(
					TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
					{ Size = UDim2New(0, 0, 0, 0), BackgroundTransparency = 1 }
				)
				task.wait(0.6)
				Items["Notification"]:Clean()
			end

			-- Click to dismiss.
			Items["Notification"]:Connect("InputBegan", function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					DismissNotification()
				end
			end)

			Library:Thread(function()
				-- Expand frame and background first.
				Items["Notification"]:Tween(
					TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
					{ Size = UDim2New(0, Size.X, 0, Size.Y), BackgroundTransparency = 0.3 }
				)

				-- Fade in text and icons after frame has mostly expanded.
				task.wait(0.3)
				for Index, Value in next, Items do
					if Value.Instance:IsA("TextLabel") then
						Value:Tween(
							TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
							{ TextTransparency = 0 }
						)
					elseif Value.Instance:IsA("ImageLabel") then
						Value:Tween(
							TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
							{ ImageTransparency = 0 }
						)
					end
				end

				-- Progress bar (accent).
				Items["Accent"]:Tween(
					TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
					{ BackgroundTransparency = 0 }
				)

				if Sticky then
					-- Unlimited duration: fill the accent and keep it up until the user clicks to dismiss (no auto-dismiss timer).
					Items["Accent"]:Tween(
						TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Size = UDim2New(1, 0, 0, 6) }
					)
				else
					Items["Accent"]:Tween(
						TweenInfo.new(Data.Duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut),
						{ Size = UDim2New(1, 0, 0, 6) }
					)

					task.delay(Data.Duration + 0.15, function()
						DismissNotification()
					end)
				end
			end)
		end

		Library.Window = function(self, Data)
			Data = Data or {}

			local function IsLaunchMenuLocked()
				return getgenv().WrathLaunchMenuLocked == true
			end

			local Window = {
				Name = Data.Name or Data.name or "Window",
				SubName = Data.SubName or Data.subname or "Fine-tuning for sure wins",
				Logo = Data.Logo or Data.logo or "1l20959262762131",

				Pages = {},
				Items = {},
				IsOpen = false,
				CurrentAlignment = "BottomTabs",
				PageSwitchLocked = false,
			}

			local Items = {}
			do
				Items["MainFrame"] = Instances:Create("Frame", {
					Parent = Library.Holder.Instance,
					Name = "\0",
					Visible = not IsLaunchMenuLocked() and not getgenv().WrathSilentMode,
					BorderColor3 = FromRGB(0, 0, 0),
					AnchorPoint = Vector2New(0.5, 0.5),
					BackgroundTransparency = 0.12,
					Position = UDim2New(0.5, 0, 0.5, 0),
					Size = UDim2New(0, 677, 0, 644),
					ZIndex = 2,
					BorderSizePixel = 0,
					BackgroundColor3 = FromRGB(27, 25, 29),
				})
				Items["MainFrame"]:AddToTheme({ BackgroundColor3 = "Background" })

				if IsMobile then
					-- Keep the complete window inside common phone/tablet viewports.
					-- The scale follows the viewport so the player can always see and drag
					-- the whole UI instead of starting with a window wider than the screen.
					local MobileScale = Instances:Create("UIScale", {
						Parent = Items["MainFrame"].Instance,
						Name = "\0",
						Scale = 0.55,
					})

					local function UpdateMobileScale()
						local Camera = workspace.CurrentCamera
						if not Camera then
							return
						end

						local Viewport = Camera.ViewportSize
						local WidthScale = (Viewport.X - 16) / 677
						local HeightScale = (Viewport.Y - 16) / 644
						local Scale = math.min(0.62, WidthScale, HeightScale)
						MobileScale.Scale = math.max(0.45, Scale)
					end

					UpdateMobileScale()
					local Camera = workspace.CurrentCamera
					if Camera then
						Library:Connect(Camera:GetPropertyChangedSignal("ViewportSize"), UpdateMobileScale)
					end
				end

				Items["MainFrame"]:MakeResizeable(
					Vector2New(Items["MainFrame"].Instance.AbsoluteSize.X, Items["MainFrame"].Instance.AbsoluteSize.Y),
					Vector2New(9999, 9999),
					OriginalSizes
				)
				Library:MakeBlurred(Items["MainFrame"], Window)

