					Parent = Items["MainFrame"].Instance,
					Name = "\0",
					Visible = false,
					BorderColor3 = FromRGB(0, 0, 0),
					AnchorPoint = Vector2New(1, 0),
					BackgroundTransparency = 0.15,
					Position = UDim2New(0, 0, 0, 0),
					Size = UDim2New(0, 225, 1, 0),
					ZIndex = 2,
					BorderSizePixel = 0,
					BackgroundColor3 = FromRGB(27, 25, 29),
				})
				Items["LeftTabs"]:AddToTheme({ BackgroundColor3 = "Background" })

				Library:MakeBlurred(Items["LeftTabs"], Window)

				-- Content sub-frame inside LeftTabs (holds UIListLayout so profile can be outside it).
				Items["LeftContent"] = Instances:Create("Frame", {
					Parent = Items["LeftTabs"].Instance,
					Name = "\0",
					BackgroundTransparency = 1,
					Size = UDim2New(1, 0, 1, -65),
					Position = UDim2New(0, 0, 0, 0),
					ZIndex = 2,
					BorderSizePixel = 0,
					ClipsDescendants = true,
				})

				Items["RightTabs"] = Instances:Create("Frame", {
					Parent = Items["MainFrame"].Instance,
					Name = "\0",
					Visible = false,
					BorderColor3 = FromRGB(0, 0, 0),
					AnchorPoint = Vector2New(0, 0),
					BackgroundTransparency = 0.15,
					Position = UDim2New(1, 0, 0, 0),
					Size = UDim2New(0, 225, 1, 0),
					ZIndex = 2,
					BorderSizePixel = 0,
					BackgroundColor3 = FromRGB(27, 25, 29),
				})
				Items["RightTabs"]:AddToTheme({ BackgroundColor3 = "Background" })
				Instances:Create(
					"UICorner",
					{ Parent = Items["RightTabs"].Instance, Name = "\0", CornerRadius = UDimNew(0, 6) }
				)
				Library:MakeBlurred(Items["RightTabs"], Window)

				-- Content sub-frame inside RightTabs.
				Items["RightContent"] = Instances:Create("Frame", {
					Parent = Items["RightTabs"].Instance,
					Name = "\0",
					BackgroundTransparency = 1,
					Size = UDim2New(1, 0, 1, -65),
					Position = UDim2New(0, 0, 0, 0),
					ZIndex = 2,
