					Items["SearchResultBox"]:Tween(
						TweenInfo.new(0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
						{
							Size = UDim2New(0, SearchOpenWidth, 0, Visible and Height or 0),
							BackgroundTransparency = Visible and 0.02 or 1,
						}
					)

					if not Visible then
						task.delay(0.18, function()
							if not SearchOpen then
								Items["SearchResultBox"].Instance.Visible = false
							end
						end)
					end
				end

