			Items["SendButton"]:Connect("MouseButton1Down", function()
				if GlobalChat:GetTypedMessage() == "" then
					return
				end

				OnMessagePressed()
			end)

			Items["Messages"]:Connect("ChildAdded", function()
				task.wait()
				Items["Messages"]:Tween(
					nil,
					{
						CanvasPosition = Vector2New(
							0,
							Items["Messages"].Instance.AbsoluteCanvasSize.Y - Items["Messages"].Instance.AbsoluteSize.Y
						),
					}
				)
			end)

			for Index, Value in next, Items["GlobalChat"].Instance:GetDescendants() do
				if not Value.ClassName:find("UI") then
					Value.ZIndex = 2
				end
			end

			Items["GlobalChat"].Instance.ZIndex = 2
			Items["SendIcon"].Instance.ZIndex = 3

			return GlobalChat
		end

