			local ExpandedSize = nil
			local ToggleDebounce = false

			function Section:ToggleBackground(Force)
				if not Section.Collapsible then
					return
				end
				if not Force and ToggleDebounce then
					return
				end
				ToggleDebounce = true
				task.delay(0.5, function()
					ToggleDebounce = false
				end)

				Section.IsActive = not Section.IsActive

				if not Section.IsActive then
					-- Save current size before collapsing.
					ExpandedSize = Items["Section"].Instance.AbsoluteSize.Y

					-- Disable auto-size so we can tween manually.
					Items["Section"].Instance.AutomaticSize = Enum.AutomaticSize.None
					Items["Section"].Instance.Size = UDim2New(1, 0, 0, ExpandedSize)

					-- Wipe up: collapse entire section to header height only.
					Items["Section"]:Tween(
						TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Size = UDim2New(1, 0, 0, 55) }
					)

					Items["Gradient"].Instance.Enabled = false
					Items["Toggle"]:ChangeItemTheme({ BackgroundColor3 = "Element" })
					Items["Toggle"]:Tween(nil, { BackgroundColor3 = Library.Theme.Element })
					Items["Circle"]:Tween(
						nil,
						{
							AnchorPoint = Vector2New(0, 0.5),
							Position = UDim2New(0, 4, 0.5, 0),
							BackgroundColor3 = FromRGB(180, 180, 180),
							BackgroundTransparency = 0,
						}
					)
				else
					-- Wipe down: expand section.
					-- Use AutomaticSize to calculate target, then tween to it.
					-- ClipsDescendants hides content during the tween.
					Items["Section"].Instance.AutomaticSize = Enum.AutomaticSize.Y
					task.wait()
					ExpandedSize = Items["Section"].Instance.AbsoluteSize.Y
					Items["Section"].Instance.AutomaticSize = Enum.AutomaticSize.None
					Items["Section"].Instance.Size = UDim2New(1, 0, 0, 55)

					Items["Section"]:Tween(
						TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Size = UDim2New(1, 0, 0, ExpandedSize) }
					)
					task.spawn(function()
						task.wait(0.45)
						Items["Section"].Instance.AutomaticSize = Enum.AutomaticSize.Y
					end)

					Items["Gradient"].Instance.Enabled = true
					Items["Toggle"]:ChangeItemTheme({ BackgroundColor3 = "Text" })
					Items["Toggle"]:Tween(nil, { BackgroundColor3 = Library.Theme.Text })
					Items["Circle"]:Tween(
						nil,
						{
							AnchorPoint = Vector2New(1, 0.5),
							Position = UDim2New(1, -4, 0.5, 0),
							BackgroundColor3 = FromRGB(0, 0, 0),
							BackgroundTransparency = 0,
						}
					)
				end
			end

			function Section:TweenElements(Bool, Debounce)
				local function TweenList(Elements)
					for Index, Value in next, Elements do
						if Value.RefreshPosition then
							Value:RefreshPosition(Bool)
						end
						-- Recurse into DependencyBox children.
						if Value.Elements then
							TweenList(Value.Elements)
						end
						-- Recurse into TabBox tabs.
						if Value.Tabs then
							for Index, Tab in next, Value.Tabs do
								if Tab.Elements then
									TweenList(Tab.Elements)
								end
							end
						end
					end
				end
				TweenList(Section.Elements)
			end

			function Section:SnapElements()
				-- Snap all elements to visible position instantly (no tween).
				local function SnapList(Elements)
					for Index, Value in next, Elements do
						pcall(function()
							if Value.Items then
								for Key, Item in next, Value.Items do
									pcall(function()
										if Item.Instance and Item.Instance:IsA("GuiObject") then
											local Pos = Item.Instance.Position
											if Pos.X.Offset >= 30 then
												Item.Instance.Position =
													UDim2New(Pos.X.Scale, Pos.X.Offset - 30, Pos.Y.Scale, Pos.Y.Offset)
											end
										end
									end)
								end
							end
						end)
						if Value.Elements then
							SnapList(Value.Elements)
						end
						if Value.Tabs then
							for Index, Tab in next, Value.Tabs do
								if Tab.Elements then
									SnapList(Tab.Elements)
								end
							end
						end
					end
				end
				SnapList(Section.Elements)
			end

			if Section.Collapsible then
				-- Use Activated for both mouse and touch. Keep MouseButton1Down as a fallback.
				Items["Toggle"].Instance.Activated:Connect(function()
					Section:ToggleBackground()
				end)
				Items["Toggle"]:Connect("MouseButton1Down", function()
					if IsMobile then return end
					Section:ToggleBackground()
				end)
			end

			Section.Page.Sections[Section.Name] = Section

			-- Tear down the section (frame + child elements). Used by module hot-reload.
			function Section:Destroy()
				pcall(function()
					if Items["Section"] and Items["Section"].Instance then
						Items["Section"].Instance:Destroy()
					end
				end)
			end

			return setmetatable(Section, Library.Sections)
		end

