			function Toggle:Get()
				return Toggle.Value
			end

			function Toggle:Set(Value)
				Toggle.Value = Value
				Library.Flags[Toggle.Flag] = Value

				if Toggle.Value then
					Items["Accent"]:Tween(
						TweenInfo.new(Library.Tween.Time + 0.1, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
						{ BackgroundTransparency = 0, Size = UDim2New(1, 0, 1, 0) }
					)
					Items["CheckImage"]:Tween(nil, { ImageTransparency = 0, Size = UDim2New(0, 10, 0, 9) })
					Items["Gradient"].Instance.Enabled = true
				else
					Items["Accent"]:Tween(
						TweenInfo.new(Library.Tween.Time + 0.05, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
						{ BackgroundTransparency = 1, Size = UDim2New(0, 0, 0, 0) }
					)
					Items["CheckImage"]:Tween(nil, { ImageTransparency = 1, Size = UDim2New(0, 0, 0, 0) })
					Items["Gradient"].Instance.Enabled = false
				end

				if Toggle.Callback then
					Library:SafeCall(Toggle.Callback, Toggle.Value)
				end
			end

