					SettingsItem["Button"]:OnHover(function()
						SettingsItem["Accent"]:Tween(
							TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
							{ Size = UDim2New(1, 0, 1, 0), BackgroundTransparency = 0 }
						)
					end)

					SettingsItem["Button"]:OnHoverLeave(function()
						SettingsItem["Accent"]:Tween(
							TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
							{ Size = UDim2New(0, 0, 0, 0), BackgroundTransparency = 1 }
						)
					end)
				end

				local RenderStepped
				local Debounce = false

				function Settings:SetOpen(Bool)
					if Debounce then
						return
					end

					Settings.IsOpen = Bool

					Debounce = true

					if Settings.IsOpen then
						task.spawn(function()
							for Index, Value in next, Settings.Elements do
								Value:RefreshPosition(true)
								task.wait(0.03)
							end
						end)

						SettingsItem["Settings"].Instance.Visible = true
						SettingsItem["Settings"].Instance.Parent = Library.Holder.Instance

						RenderStepped = RunService.RenderStepped:Connect(function()
							SettingsItem["Settings"].Instance.Position = UDim2New(
								0,
								Items["Toggle"].Instance.AbsolutePosition.X
									+ Items["Toggle"].Instance.AbsoluteSize.X / 1.9
									+ 15,
								0,
								Items["Toggle"].Instance.AbsolutePosition.Y
									+ Items["Toggle"].Instance.AbsoluteSize.Y
									+ Size / 1.9
							)
							SettingsItem["Settings"].Instance.Size = UDim2New(0, 245, 0, Size)
						end)

						for Index, Value in next, Library.OpenFrames do
							if Value ~= Settings then
								pcall(Value.SetOpen, Value, false)
							end
						end

						Library.OpenFrames[Settings] = Settings
					else
						for Index, Value in next, Settings.Elements do
							Value:RefreshPosition(false)
						end

						if Library.OpenFrames[Settings] then
							Library.OpenFrames[Settings] = nil
						end

						if RenderStepped then
							RenderStepped:Disconnect()
							RenderStepped = nil
						end
					end

					local Descendants = SettingsItem["Settings"].Instance:GetDescendants()
					TableInsert(Descendants, SettingsItem["Settings"].Instance)

					local NewTween

					for Index, Value in next, Descendants do
						local TransparencyProperty = Tween:GetProperty(Value)

						if TransparencyProperty then
							if not Value.ClassName:find("UI") then
								Value.ZIndex = Settings.IsOpen and 7 or 1
							end

							if type(TransparencyProperty) == "table" then
								for Index, Property in next, TransparencyProperty do
									NewTween = Tween:FadeItem(Value, Property, Bool, Library.FadeSpeed)
								end
							else
								NewTween = Tween:FadeItem(Value, TransparencyProperty, Bool, Library.FadeSpeed)
							end
						end
					end

					NewTween.Tween.Completed:Connect(function()
						Debounce = false
						SettingsItem["Settings"].Instance.Visible = Settings.IsOpen
						task.wait(0.2)
						SettingsItem["Settings"].Instance.Parent = not Settings.IsOpen and Library.UnusedHolder.Instance
							or Library.Holder.Instance
					end)
				end

				SettingsItem["Button"]:Connect("MouseButton1Down", function()
					Settings:SetOpen(false)
				end)

				SettingsItem["SettingsIcon"]:Connect("InputBegan", function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						or Input.UserInputType == Enum.UserInputType.Touch
					then
						Settings:SetOpen(not Settings.IsOpen)
					end
				end)

				Library:Connect(UserInputService.InputBegan, function(Input)
					if
						Input.UserInputType == Enum.UserInputType.MouseButton1
						or Input.UserInputType == Enum.UserInputType.Touch
					then
						if Library:IsMouseOverFrame(SettingsItem["Settings"]) then
							return
						end

						Settings:SetOpen(false)
					end
				end)

				Settings.Items = SettingsItem

				setmetatable(Settings, Library.Sections)
				return Settings
			end

			function Toggle:SetVisibility(Bool)
				Items["Toggle"].Instance.Visible = Bool
			end

			function Toggle:Colorpicker(Data)
				Data = Data or {}

				local Colorpicker = {
					Window = Toggle.Window,
					Page = Toggle.Page,
					Section = Toggle.Section,

					Flag = Data.Flag or Data.flag or Library:NextFlag(),
					Default = Data.Default or Data.default or Color3.fromRGB(255, 255, 255),
					Callback = Data.Callback or Data.callback or function() end,
					Alpha = Data.Alpha or Data.alpha or false,
				}

				local NewColorpicker, ColorpickerItems = Library:CreateColorpicker({
					Parent = Items["SubElements"],
					Page = Colorpicker.Page,
					Section = Colorpicker.Section,
					Flag = Colorpicker.Flag,
					Default = Colorpicker.Default,
					Callback = Colorpicker.Callback,
					Alpha = Colorpicker.Alpha,
				})

				return NewColorpicker
			end

			function Toggle:Keybind(Data)
				Data = Data or {}

				local Keybind = {
					Window = Toggle.Window,
					Page = Toggle.Page,
					Section = Toggle.Section,

					Flag = Data.Flag or Data.flag or Library:NextFlag(),
					Default = Data.Default or Data.default or Enum.KeyCode.E,
					Callback = Data.Callback or Data.callback or function() end,
					Mode = Data.Mode or Data.mode or "Toggle",
				}

				local NewKeybind, KeybindItems = Library:CreateKeybind({
					Parent = Items["SubElements"],
					Name = Toggle.Name,
					Page = Keybind.Page,
					Section = Keybind.Section,
					Flag = Keybind.Flag,
					Default = Keybind.Default,
					Mode = Keybind.Mode,
					Callback = Keybind.Callback,
				})

				return NewKeybind
			end

			function Toggle:RefreshPosition(Bool)
				if Bool then
					Items["Indicator"]:Tween(
						TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Position = UDim2New(0, 0, 0, 0) }
					)
					Items["Text"]:Tween(
						TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Position = UDim2New(0, 24, 0, 0) }
					)
				else
					Items["Indicator"].Instance.Position = UDim2New(0, 60, 0, 0)
					Items["Text"].Instance.Position = UDim2New(0, 84, 0, 0)
				end
			end

			-- Use GuiButton.Activated for toggles. Unlike MouseButton1Down, Activated is
			-- fired for both mouse clicks and touch taps, so mobile can reliably toggle
			-- features on and off. The toggle button is Active so touches are captured
			-- by the button even though its visual children sit on top of it.
			local LastToggleClick = 0
			Items["Toggle"].Instance.Activated:Connect(function()
				local Now = os.clock()
				if Now - LastToggleClick < 0.12 then
					return
				end
				LastToggleClick = Now

				if Items["SettingsIcon"] and Library:IsMouseOverFrame(Items["SettingsIcon"]) then
					return
				end

				Toggle:Set(not Toggle.Value)
			end)

			Toggle:Set(Toggle.Default)

			Library.SetFlags[Toggle.Flag] = function(Value)
				Toggle:Set(Value)
			end

			Toggle.Items = Items
			Toggle.UiItems = Items
			Toggle.Section.Elements[#Toggle.Section.Elements + 1] = Toggle

			return Toggle
		end

		Library.Sections.Button = function(self, Data)
			Data = Data or {}

			local Button = {
				Window = self.Window,
				Page = self.Page,
				Section = self,

				Name = Data.Name or Data.name or "Button",
				Icon = Data.Icon or Data.icon or nil,
				Callback = Data.Callback or Data.callback or function() end,
			}

			local Items = {}
			do
				Items["Button"] = Instances:Create("TextButton", {
					Parent = Button.Section.Items["Content"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = FromRGB(0, 0, 0),
					BorderColor3 = FromRGB(0, 0, 0),
					Text = "",
					AutoButtonColor = false,
					BorderSizePixel = 0,
					Size = UDim2New(1, 0, 0, 32),
					ZIndex = 2,
					TextSize = 14,
					BackgroundColor3 = FromRGB(27, 26, 29),
				})
				Items["Button"]:AddToTheme({ BackgroundColor3 = "Element" })

				Items["Accent"] = Instances:Create("Frame", {
					Parent = Items["Button"].Instance,
					Name = "\0",
					Size = UDim2New(0, 0, 0, 0),
					BorderColor3 = FromRGB(0, 0, 0),
					ZIndex = 2,
					BorderSizePixel = 0,
					BackgroundTransparency = 1,
					BackgroundColor3 = FromRGB(255, 255, 255),
					AnchorPoint = Vector2New(0.5, 0.5),
					Position = UDim2New(0.5, 0, 0.5, 0),
				}) --Items["Accent"]:AddToTheme({BackgroundColor3 = "Accent"})

				Items["Gradient"] = Instances:Create("UIGradient", {
					Parent = Items["Accent"].Instance,
					Name = "\0",
					Enabled = true,
					Rotation = -115,
					Color = RGBSequence({
						RGBSequenceKeypoint(0, FromRGB(255, 255, 255)),
						RGBSequenceKeypoint(1, FromRGB(143, 143, 143)),
					}),
				})
				Items["Gradient"]:AddToTheme({
					Color = function()
						return RGBSequence({
							RGBSequenceKeypoint(0, Library.Theme.Accent),
							RGBSequenceKeypoint(1, Library.Theme.AccentGradient),
						})
					end,
				})

				Instances:Create("UICorner", {
					Parent = Items["Accent"].Instance,
					Name = "\0",
					CornerRadius = UDimNew(0, 4),
				})

				Instances:Create("UICorner", {
					Parent = Items["Button"].Instance,
					Name = "\0",
					CornerRadius = UDimNew(0, 4),
				})

				Items["Text"] = Instances:Create("TextLabel", {
					Parent = Items["Button"].Instance,
					Name = "\0",
					FontFace = Library.Font,
					TextColor3 = Library.Theme.Text,
					TextTransparency = 0.3,
					Text = Button.Name,
					AutomaticSize = Enum.AutomaticSize.X,
					Size = UDim2New(0, 0, 0, 15),
					AnchorPoint = Vector2New(0.5, 0.5),
					BorderSizePixel = 0,
					BackgroundTransparency = 1,
					Position = UDim2New(0.5, 0, 0.5, 0),
					BorderColor3 = FromRGB(0, 0, 0),
					ZIndex = 2,
					TextSize = 14,
					BackgroundColor3 = FromRGB(255, 255, 255),
				})
				Items["Text"]:AddToTheme({ TextColor3 = "Text" })

				if Button.Icon then
					Items["Icon"] = Instances:Create("ImageLabel", {
						Parent = Items["Text"].Instance,
						Name = "\0",
						ImageColor3 = Library.Theme.Text,
						ImageTransparency = 0.3,
						BorderColor3 = FromRGB(0, 0, 0),
						Size = UDim2New(0, 18, 0, 18),
						AnchorPoint = Vector2New(1, 0.5),
						Image = "rbxassetid://" .. Button.Icon,
						BackgroundTransparency = 1,
						Position = UDim2New(0, -8, 0.5, 0),
						ZIndex = 2,
						BorderSizePixel = 0,
						BackgroundColor3 = FromRGB(255, 255, 255),
					})
					Items["Icon"]:AddToTheme({ ImageColor3 = "Text" })
				end

				local IsHovering = false

				Items["Button"]:OnHover(function()
					IsHovering = true
					Items["Accent"]:Tween(
						TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Size = UDim2New(1, 0, 1, 0), BackgroundTransparency = 0 }
					)
					Items["Text"]:Tween(
						TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ TextColor3 = FromRGB(0, 0, 0), TextTransparency = 0 }
					)
				end)

				Items["Button"]:OnHoverLeave(function()
					IsHovering = false
					Items["Accent"]:Tween(
						TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Size = UDim2New(0, 0, 0, 0), BackgroundTransparency = 1 }
					)
					Items["Text"]:Tween(
						TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ TextColor3 = Library.Theme.Text, TextTransparency = 0.3 }
					)
				end)
			end

			if Button.Section.Items["Fade"] then
				Button.Section.Items["Fade"].Instance.Size =
					UDim2New(1, 0, 0, math.max(0, Button.Section.Items["Content"].Instance.AbsoluteSize.Y - 180))
			end

			function Button:SetVisibility(Bool)
				Items["Button"].Instance.Visible = Bool
			end

			function Button:Press()
				Items["Button"]:ChangeItemTheme({ BackgroundColor3 = "Accent" })
				Items["Button"]:Tween(nil, { BackgroundColor3 = Library.Theme.Accent })

				-- Flash text white on press.
				Items["Text"]:Tween(nil, { TextColor3 = Library.Theme.Text, TextTransparency = 0 })

				if Button.Icon then
					Items["Icon"]:Tween(nil, { ImageColor3 = Library.Theme.Text, ImageTransparency = 0 })
				end

				task.wait(0.2)

				Library:SafeCall(Button.Callback)
				Items["Button"]:ChangeItemTheme({ BackgroundColor3 = "Element" })
				Items["Button"]:Tween(nil, { BackgroundColor3 = Library.Theme.Element })

				-- Check hover state directly via GuiState.
				local StillHovering = Items["Button"].Instance.GuiState == Enum.GuiState.Hover

				if StillHovering then
					Items["Accent"]:Tween(
						TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ Size = UDim2New(1, 0, 1, 0), BackgroundTransparency = 0 }
					)
					Items["Text"]:Tween(
						TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
						{ TextColor3 = FromRGB(0, 0, 0), TextTransparency = 0 }
					)

					if Button.Icon then
						Items["Icon"]:Tween(nil, { ImageColor3 = FromRGB(0, 0, 0), ImageTransparency = 0 })
					end
				else
					Items["Text"]:Tween(nil, { TextColor3 = Library.Theme.Text, TextTransparency = 0.3 })

					if Button.Icon then
						Items["Icon"]:Tween(nil, { ImageColor3 = Library.Theme.Text, ImageTransparency = 0.3 })
					end
				end
			end

			Items["Button"]:Connect("MouseButton1Down", function()
				Button:Press()
			end)

			Button.Items = Items
			Button.UiItems = Items
			Button.Section.Elements[#Button.Section.Elements + 1] = Button

			return Button
		end

