    ["x"] = "",
    ["sprout"] = "",
    ["palette"] = "",
    ["keyboard"] = "",
    ["send"] = "",
    ["chevron-down"] = "",
    ["chevron-right"] = "",
    ["swords"] = "",
    ["radio"] = "",
    ["save"] = "",
    ["puzzle"] = "",
    ["crosshair"] = "",
    ["scroll-text"] = "",
    ["music"] = "",
    ["monitor"] = "",
    ["database"] = "",
    ["eye"] = "",
    ["zap"] = "",
    ["play"] = "",
    ["pause"] = "",
    ["skip-back"] = "",
    ["skip-forward"] = "",
    ["chevron-left"] = "",
    ["list"] = "",
    ["users-round"] = "",
}
local WrathUiIcons = {}
local function DecodeWrathIconBase64(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local output, buffer, bits = {}, 0, 0
    for i = 1, #data do
        local char = data:sub(i, i)
        if char == "=" then break end
        local value = string.find(alphabet, char, 1, true)
        if value then
            buffer = buffer * 64 + value - 1
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                output[#output + 1] = string.char(math.floor(buffer / (2 ^ bits)) % 256)
                buffer = buffer % (2 ^ bits)
            end
        end
    end
    return table.concat(output)
end
local function LoadWrathUiIcon(name, encoded)
    local assetFn = (type(getcustomasset) == "function" and getcustomasset)
        or (type(getsynasset) == "function" and getsynasset)
    if type(assetFn) ~= "function" or type(writefile) ~= "function" then return "" end
    local ok, asset = pcall(function()
        local folder = "Wrath/Icons"
        if type(isfolder) == "function" and not isfolder("Wrath") and type(makefolder) == "function" then
            makefolder("Wrath")
        end
        if type(isfolder) == "function" and not isfolder(folder) and type(makefolder) == "function" then
            makefolder(folder)
        end
        local path = folder .. "/" .. name .. "_" .. #encoded .. ".png"
        if type(isfile) ~= "function" or not isfile(path) then
            writefile(path, DecodeWrathIconBase64(encoded))
        end
        return assetFn(path)
    end)
    return ok and type(asset) == "string" and asset or ""
end
for name, encoded in pairs(WrathUiIconData) do
    WrathUiIcons[name] = LoadWrathUiIcon(name, encoded)
end

