local NativeWindow = Library:Window({ Name = "Untitled Boxing Game", SubName = "LINH HUB", Logo = LinhLogo })
-- Keep the original Wrath-style bottom tab dock.
NativeWindow.CurrentAlignment = "BottomTabs"
local Window = {}
function Window:CreateTab(data)
    local name = type(data) == "table" and data.Name or tostring(data)
    local icon = type(data) == "table" and data.Icon or ""
    local page = NativeWindow:Page({ Name = name, Icon = icon or "", Columns = 2 })
    local tab = {}
    local sectionCount = 0
    function tab:CreateSection(sectionName)
        local sectionIcon = type(sectionName) == "table" and sectionName.Icon or nil
        if type(sectionName) == "table" then sectionName = sectionName.Name or "Section" end
        if not sectionIcon and type(sectionName) == "string" then
            local sectionIcons = {
                ["Auto Dodge"] = WrathUiIcons["skip-forward"],
                ["Auto Block"] = WrathUiIcons["pause"],
                ["Auto Punch"] = WrathUiIcons["unlink"],
                ["Settings"] = WrathUiIcons["settings"],
                ["Keybinds"] = WrathUiIcons["keyboard"],
                ["Configs"] = WrathUiIcons["database"],
                ["Utility"] = WrathUiIcons["scroll-text"],
            }
            sectionIcon = sectionIcons[sectionName]
        end
        sectionCount = sectionCount + 1
        -- Alternate each section between the two columns for a two-by-two layout.
        local side = ((sectionCount - 1) % 2) + 1
        local section = page:Section({ Name = sectionName, Side = side, Icon = sectionIcon })
        local compat = {}
        function compat:CreateToggle(opts)
            opts = opts or {}
            return section:Toggle({ Name = opts.Name or "Toggle", Default = opts.CurrentValue == true, Callback = opts.Callback })
        end
        function compat:CreateSlider(opts)
            opts = opts or {}
            local range = opts.Range or {0, 100}
            local increment = tonumber(opts.Increment) or 1
            local decimals = 0
            if increment < 1 then
                decimals = math.max(1, math.ceil(-math.log10(increment)))
            end
            return section:Slider({ Name = opts.Name or "Slider", Min = range[1], Max = range[2], Default = opts.CurrentValue or range[1], Decimals = decimals, Callback = opts.Callback })
        end
        function compat:CreateButton(opts)
            opts = opts or {}
            return section:Button({ Name = opts.Name or "Button", Callback = opts.Callback })
        end
        function compat:CreateLabel(text)
            return section:Label(tostring(text or ""))
        end
        return compat
    end
    return tab
end

local Tabs = {
    Combat = Window:CreateTab({ Name = "Combat", Icon = WrathUiIcons["unlink"] }),
    Automation = Window:CreateTab({ Name = "Automation", Icon = WrathUiIcons["skip-forward"] }),
    ESP = Window:CreateTab({ Name = "ESP", Icon = WrathUiIcons["monitor"] }),
    Misc = Window:CreateTab({ Name = "Misc", Icon = WrathUiIcons["keyboard"] }),
    Settings = Window:CreateTab({ Name = "Settings", Icon = WrathUiIcons["settings"] }),
}

-- ============================================================
-- GAME STATE HELPERS
-- ============================================================
local function getStates()
	return Workspace:FindFirstChild("States")
end

local function getMyState()
	local s = getStates()
	return s and s:FindFirstChild(LocalPlayer.Name)
end

local function getMyOcc()
	local st = getMyState()
	return st and st:FindFirstChild("Occupied")
end

local function myVal(parent, name)
	local f = parent and parent:FindFirstChild(name)
	return f and f.Value
end

local function myOccVal(name)
	return myVal(getMyOcc(), name)
end

local function myCdVal(name)
	local st = getMyState()
	local cd = st and st:FindFirstChild("CharacterData")
	return myVal(cd, name)
end

local function getOpponent()
	local st = getMyState()
	local occ = st and st:FindFirstChild("Occupied")
	local locked = occ and occ:FindFirstChild("LockedOn")
	if locked and locked.Value then
		return locked.Value
	end
	local cd = st and st:FindFirstChild("CharacterData")
	local opp = cd and cd:FindFirstChild("Opponent")
	return opp and opp.Value
end

local function occVal(model, name)
	local s = getStates()
	local st = s and s:FindFirstChild(model.Name)
	local occ = st and st:FindFirstChild("Occupied")
	return myVal(occ, name)
end

local function rootOf(model)
	return model and model:FindFirstChild("HumanoidRootPart")
end

local function distBetween(a, b)
	if not a or not b then return math.huge end
	return (a.Position - b.Position).Magnitude
end

local function inputAllowed()
	if type(isrbxactive) == "function" and not isrbxactive() then return false end
	if UserInputService:GetFocusedTextBox() then return false end
	return true
end

-- ============================================================
-- BRIDGES / EVENTS
-- ============================================================
local BridgeNet2 = nil
pcall(function()
	local mod = ReplicatedFirst:WaitForChild("Bridge" .. "Net2", 5)
	if mod then
		BridgeNet2 = require(mod :: ModuleScript)
	end
end)

local function refBridge(name)
	if BridgeNet2 then
		local ok, b = pcall(function() return BridgeNet2.ReferenceBridge(name) end)
		if ok and b then return b end
	end
	local remotes = ReplicatedStorage:FindFirstChild("RemoteEvents")
	return remotes and remotes:FindFirstChild(name)
end

local function fireNamed(name, ...)
	local args = { ... }
	local b = refBridge(name)
	if not b then return false end
	if type(b.FireServer) == "function" then
		return pcall(function() b:FireServer(unpack(args)) end)
	end
	return pcall(function() b:Fire(unpack(args)) end)
end

local function fireEvent(name, ...)
	local args = { ... }
	local e = ReplicatedStorage:FindFirstChild("Events")
	local ev = e and e:FindFirstChild(name)
	if not ev then return false end
	return pcall(function() ev:Fire(unpack(args)) end)
end

-- ============================================================
-- COMBAT > AUTO DODGE (port of CDHW/Kohrynth script)
-- ============================================================
local Dodge = { Enabled = true, Range = 14 }
local lastPerfect

local function runDodge()
	if not Dodge.Enabled or not _k.v then return end

	local character = LocalPlayer.Character
	if not character then return end

	local perfect = character:GetAttribute("Perfect")
	if perfect == nil or perfect == lastPerfect then return end

	local direction = character:GetAttribute("NeededDirection")
	if direction ~= "Left" and direction ~= "Right" and direction ~= "Backward" and direction ~= "Forward" then return end

	local opponent = getOpponent()
	if not opponent then return end

	if opponent:GetAttribute("IsFeinting") == true or opponent:GetAttribute("LocalIsFeinting") == true then return end

	local root = rootOf(character)
	local eroot = rootOf(opponent)
	if root and eroot and (root.Position - eroot.Position).Magnitude > Dodge.Range then return end

	if myOccVal("Dashing") then return end

	lastPerfect = perfect
	fireEvent("ForceDash", { Direction = direction })

	RunService.Heartbeat:Once(function()
		if _k.v and Dodge.Enabled and LocalPlayer.Character == character
			and character:GetAttribute("Perfect") == perfect and not myOccVal("Dashing") then
			fireEvent("ForceDash", { Direction = direction })
		end
	end)
	RunService.Heartbeat:Once(function()
		if _k.v and Dodge.Enabled and LocalPlayer.Character == character
			and character:GetAttribute("Perfect") == perfect and not myOccVal("Dashing") then
			fireEvent("ForceDash", { Direction = direction })
		end
	end)
end

local dodgeConn = RunService.Heartbeat:Connect(function()
	if Running and _k.v then
		runDodge()
	end
end)
onCleanup(function() pcall(function() dodgeConn:Disconnect() end) end)

local dodgeCharConn = LocalPlayer.CharacterAdded:Connect(function()
	lastPerfect = nil
end)
onCleanup(function() pcall(function() dodgeCharConn:Disconnect() end) end)

do
	local section = Tabs.Combat:CreateSection("Auto Dodge")
	section:CreateToggle({
		Name = "Auto Dodge",
		CurrentValue = Dodge.Enabled,
		Callback = function(v)
			Dodge.Enabled = v
			if v then lastPerfect = nil end
		end,
	})
	section:CreateSlider({
		Name = "Dodge Range",
		Range = { 4, 25 },
		Increment = 1,
		CurrentValue = Dodge.Range,
		Callback = function(v) Dodge.Range = v end,
	})
end

-- ============================================================
-- COMBAT > AUTO BLOCK
-- Runs on Heartbeat exactly like Auto Dodge, drives the real
-- F key (keydown/keyup) - no remote fallback.
-- ============================================================
local Block = { Enabled = false, Range = 10, ReleaseMs = 700 }
local BLOCK_VK = 0x46 -- Enum.KeyCode.F

local blockHolding = false
local lastBlockPress = 0
local lastIncoming = -math.huge
local lastOpp = nil
local lastOppPunchAttr = nil
local lastReTap = 0
local rePressAt = nil

local function pressBlock()
	if blockHolding then return end
	if type(isrbxactive) == "function" and not isrbxactive() then return end
	if UserInputService:GetFocusedTextBox() then return end
	if type(keypress) ~= "function" then return end
	blockHolding = true
	lastBlockPress = os.clock()
	pcall(keypress, BLOCK_VK)
end

local function releaseBlock()
	if not blockHolding then return end
	blockHolding = false
	if type(keyrelease) == "function" then pcall(keyrelease, BLOCK_VK) end
end

local blockConn = RunService.Heartbeat:Connect(function()
	if not Running or not _k.v or not Block.Enabled then
		releaseBlock()
		lastIncoming = -math.huge
		return
	end

	local myChar = LocalPlayer.Character
	if not myChar then
		releaseBlock()
		return
	end

	if blockHolding and os.clock() - lastBlockPress > 0.15
		and not UserInputService:IsKeyDown(Enum.KeyCode.F) then
		blockHolding = false
	end

	local opponent = getOpponent()
	if opponent ~= lastOpp then
		lastOpp = opponent
		lastOppPunchAttr = nil
	end

	local now = os.clock()
	local incoming = false
	local feinting = false

	if opponent then
		feinting = opponent:GetAttribute("IsFeinting") == true
			or opponent:GetAttribute("LocalIsFeinting") == true

		if not feinting then
			local kd = opponent:GetAttribute("KnockedDown")
			local knocked = kd == true or (type(kd) == "number" and kd ~= 0)
			if not knocked then
				local punchBool = occVal(opponent, "Punching") == true
				local attr = opponent:GetAttribute("Punching")
				local attrChanged = lastOppPunchAttr ~= nil and attr ~= nil and attr ~= lastOppPunchAttr
				if punchBool or attrChanged then
					local d = distBetween(rootOf(myChar), rootOf(opponent))
					if d <= Block.Range then
						incoming = true
					end
				end
			end
		end
		lastOppPunchAttr = opponent:GetAttribute("Punching")
	end

	-- Last resort: my perfect-dodge window means the punch is landing now
	if not incoming and not feinting and myChar:GetAttribute("Perfect") ~= nil then
		incoming = true
	end

	if incoming then
		lastIncoming = now
	end

	if now - lastIncoming <= Block.ReleaseMs / 1000 then
		local canNow = myOccVal("CanBlock") ~= false
			and myOccVal("Stunned") ~= true
			and myOccVal("Dashing") ~= true
			and myCdVal("Cutscene") ~= true
			and (myCdVal("Health") or 0) > 0
		if not canNow then
			rePressAt = nil
			releaseBlock()
		else
			-- The game drops Blocking on its own (hit reaction / server
			-- unblock). A held key never fires InputBegan again, so block
			-- dies after one hit - tap F to restart TryBlock.
			local gameBlocking = myOccVal("Blocking") == true
			local keyDown = UserInputService:IsKeyDown(Enum.KeyCode.F)
			if rePressAt then
				if now >= rePressAt then
					rePressAt = nil
					pressBlock()
				end
			elseif (blockHolding or keyDown) and not gameBlocking
				and now - lastBlockPress > 0.35
				and now - lastReTap > 0.35 then
				lastReTap = now
				releaseBlock()
				rePressAt = now + 0.05
			else
				pressBlock()
			end
		end
	else
		rePressAt = nil
		releaseBlock()
	end
end)
onCleanup(function()
	pcall(function() blockConn:Disconnect() end)
	releaseBlock()
end)

do
	local section = Tabs.Combat:CreateSection("Auto Block")
	section:CreateToggle({
		Name = "Auto Block",
		CurrentValue = Block.Enabled,
		Callback = function(v)
			Block.Enabled = v
			lastIncoming = -math.huge
			rePressAt = nil
			if not v then releaseBlock() end
		end,
	})
	section:CreateSlider({
		Name = "Block Range",
		Range = { 4, 20 },
		Increment = 1,
		CurrentValue = Block.Range,
		Callback = function(v) Block.Range = v end,
	})
	section:CreateSlider({
		Name = "Release Delay (ms)",
		Range = { 0, 1500 },
		Increment = 50,
		CurrentValue = Block.ReleaseMs,
		Callback = function(v) Block.ReleaseMs = v end,
	})
	section:CreateLabel("Holds F the frame your opponent punches - feints are ignored")
end

-- ============================================================
-- COMBAT > AUTO PUNCH
-- ============================================================
local Punch = { Enabled = false, Range = 6, Interval = 0.35, HeavyEvery = 4 }
local lastPunch = 0
local punchStep = 0
local combatCtrl, combatCls

-- The game's own controller: CombatShared instance exposes TryPunch() /
-- TryPunch({ IsHeavy = true }) - same API its built-in combo uses.
local filtergcAny = filtergc :: any
local function getCombatCtrl()
	local char = LocalPlayer.Character
	if combatCtrl then
		local rp = rawget(combatCtrl, "RootPart")
		if typeof(rp) == "Instance" and char and rp.Parent == char then
			return combatCtrl
		end
		combatCtrl = nil
	end
	if not combatCls then
		local ok, cls = pcall(filtergcAny, "table", { Keys = { "TryPunch", "New" } }, true)
		if not ok or type(cls) ~= "table" then return nil end
		combatCls = cls
	end
	local ok, found = pcall(filtergcAny, "table", { Metatable = combatCls })
	if not ok or type(found) ~= "table" then return nil end
	for _, inst in ipairs(found) do
		if type(inst) == "table" and inst ~= combatCls then
			local rp = rawget(inst, "RootPart")
			if typeof(rp) == "Instance" and char and rp.Parent == char then
				combatCtrl = inst
				return inst
			end
		end
	end
	return nil
end

local punchDiag = { last = "init", err = "", d = -1, target = "-", t = 0, moves = 0 }

local function isAliveModel(m)
	if not m then return false end
	local h = m:FindFirstChildOfClass("Humanoid")
	return h ~= nil and h.Health > 0 and rootOf(m) ~= nil
end

local function isKnocked(m)
	local kd = m and m:GetAttribute("KnockedDown")
	return kd == true or (type(kd) == "number" and kd ~= 0)
end

-- LockedOn/Opponent clear or go stale after a takedown. While we are in
-- combat (our arena flag off), pick the nearest live fighter instead of
-- stalling until the game re-locks for us.
local function nearestCombatOpponent()
	if myCdVal("InSafezone") == true then return nil end
	local myRoot = rootOf(LocalPlayer.Character)
	if not myRoot then return nil end
	local states = getStates()
	if not states then return nil end
	local best, bestD = nil, 90
	for _, pl in ipairs(game.Players:GetPlayers()) do
		if pl ~= LocalPlayer then
			local c = pl.Character
			if isAliveModel(c) and not isKnocked(c) then
				local st = states:FindFirstChild(pl.Name)
				local cd = st and st:FindFirstChild("CharacterData")
				if cd and myVal(cd, "InSafezone") ~= true then
					local d = distBetween(myRoot, rootOf(c))
					if d < bestD then
						best, bestD = c, d
					end
				end
			end
		end
	end
	return best
end

local punchLoop = task.spawn(function()
	local moveCancel = false
	local lastMoveTo = nil
	local lastMoveToAt = 0
	while Running do
		task.wait(0.05)
		local ok, err = pcall(function()
			punchDiag.t = os.clock()
			if not _k.v then
				punchDiag.last = "key"
				return
			end
			if not Punch.Enabled then
				punchDiag.last = "disabled"
				return
			end
			if not inputAllowed() then
				punchDiag.last = "input"
				return
			end

			local opponent = getOpponent()
			if not isAliveModel(opponent) then
				opponent = nil
			end
			if not opponent then
				opponent = nearestCombatOpponent()
			end
			if not opponent then
				punchDiag.last = "no-target"
				return
			end

			local myChar = LocalPlayer.Character
			local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
			local myRoot = rootOf(myChar)
			local oRoot = rootOf(opponent)
			if not myHum or myHum.Health <= 0 or not myRoot or not oRoot then
				punchDiag.last = "no-root"
				return
			end

			local d = distBetween(myRoot, oRoot)
			punchDiag.d = math.floor(d)
			punchDiag.target = opponent.Name

			-- Close the distance while in combat. Re-issue MoveTo sparingly:
			-- calling it every tick restarts pathfinding and the character
			-- barely moves.
			local canMove = myOccVal("Stunned") ~= true
				and myCdVal("Cutscene") ~= true
				and not isKnocked(myChar)
			if canMove then
				if d > Punch.Range - 1.5 then
					local nowT = os.clock()
					local shouldIssue = not lastMoveTo
						or (oRoot.Position - lastMoveTo).Magnitude > 3
						or nowT - lastMoveToAt > 1.2
					if shouldIssue then
						myHum:MoveTo(oRoot.Position)
						lastMoveTo = oRoot.Position
						lastMoveToAt = nowT
						punchDiag.moves = (punchDiag.moves or 0) + 1
					end
					moveCancel = true
					punchDiag.last = "approach"
				elseif moveCancel then
					myHum:MoveTo(myRoot.Position)
					moveCancel = false
					lastMoveTo = nil
				end
			end

			if isKnocked(opponent) then
				punchDiag.last = "target-knocked"
				return
			end

			local canPunch = myOccVal("CanPunch") == true
			local stunned = myOccVal("Stunned") == true
			local blocking = myOccVal("Blocking") == true
			if d <= Punch.Range and canPunch and not stunned and not blocking
				and os.clock() - lastPunch >= Punch.Interval then
				local heavy = Punch.HeavyEvery > 0
					and (punchStep % Punch.HeavyEvery) == (Punch.HeavyEvery - 1)
				punchStep = punchStep + 1
				local ctrl = getCombatCtrl()
				local threw = false
				if ctrl then
					threw = pcall(function()
						if heavy then
							ctrl:TryPunch({ IsHeavy = true })
						else
							ctrl:TryPunch()
						end
					end)
				end
				if not threw then
					heavy = false
					pcall(mouse1click)
				end
				lastPunch = os.clock() + (heavy and 0.55 or 0)
				punchDiag.last = heavy and "punched-heavy" or "punched"
			elseif d > Punch.Range then
				punchDiag.last = "range"
			elseif not canPunch then
				punchDiag.last = "canPunch"
			elseif stunned then
				punchDiag.last = "stunned"
			elseif blocking then
				punchDiag.last = "blocking"
			else
				punchDiag.last = "interval"
			end
		end)
		if not ok then
			punchDiag.err = tostring(err)
			punchDiag.last = "error"
		end
	end
end)

