-- ============================================================
-- AUTOMATION > STYLE SPIN
-- ============================================================
local Spin = { Enabled = false }
local spinWarned = false

local function doSpinAttempt()
	local gui = LocalPlayer.PlayerGui:FindFirstChild("Main")
	local ss = gui and gui:FindFirstChild("StyleShop")
	if not ss then return false end

	local spinning = ss:FindFirstChild("Spinning")
	if spinning and spinning.Value then return false end

	local spin = ss:FindFirstChild("Spin")
	if not spin then return false end

	local free = false
	local sl = spin:FindFirstChild("SpinsLeft")
	if sl then free = sl.Visible == true end

	local priceText = ""
	local pr = spin:FindFirstChild("Price")
	if pr then priceText = tostring(pr.Text) end

	local stripped = string.gsub(priceText, "[^%d]", "")
	local price = tonumber(stripped) or 0

	local cash = 0
	local st = getMyState()
	local pd = st and st:FindFirstChild("PlayerData")
	local cf = pd and pd:FindFirstChild("Cash")
	if cf then cash = tonumber(cf.Value) or 0 end

	if free or cash >= price then
		spinWarned = false
		return fireNamed("TrySpin")
	end

	if Spin.Enabled and not spinWarned then
		spinWarned = true
		notify("Auto Spin: not enough cash for a spin (" .. priceText .. ")", "Error", 4)
	end
	return false
end

local spinLoop = task.spawn(function()
	while Running do
		task.wait(1)
		if not _k.v then continue end
		if Spin.Enabled then
			doSpinAttempt()
		end
	end
end)

do
	local section = Tabs.Automation:CreateSection("Style Spin")
	section:CreateToggle({
		Name = "Auto Spin",
		CurrentValue = Spin.Enabled,
		Callback = function(v)
			Spin.Enabled = v
			spinWarned = false
		end,
	})
	section:CreateButton({
		Name = "Spin Once",
		Callback = function()
			if not _k.v then return end
			if doSpinAttempt() then
				notify("Spin started!", "Success", 2)
			else
				notify("Could not spin (spinning already / no cash)", "Error", 3)
			end
		end,
	})
	section:CreateLabel("Uses free spins first, then cash ($2,000 per spin)")
end

