-- AUTOMATION > CODES
-- ============================================================
local REDEEM_CODES = { "deimos", "terror", "3years", "lynn", "justtakethecash", "ubgliveson", "freeemoteforall" }
local redeeming = false

local function redeemAll()
	if redeeming or not _k.v then return end
	redeeming = true

	local results = {}
	local conn = nil
	pcall(function()
		local b = refBridge("CodeResult")
		if b and type(b.Connect) == "function" then
			conn = b:Connect(function(payload)
				if type(payload) == "table" then
					table.insert(results, payload)
				end
			end)
		end
	end)

	for _, code in ipairs(REDEEM_CODES) do
		if not Running or not _k.v then break end
		fireNamed("TryCode", code)
		task.wait(1.2)
	end
	task.wait(0.6)

	if conn then pcall(function() conn:Disconnect() end) end

	local msgs = {}
	for _, payload in ipairs(results) do
		if payload.message then
			table.insert(msgs, tostring(payload.message))
		end
	end
	if #msgs > 0 then
		notify(table.concat(msgs, " | "), "Success", 6)
	else
		notify("Sent " .. #REDEEM_CODES .. " codes (results arrive in chat)", "Info", 4)
	end
	redeeming = false
end

do
	local section = Tabs.Automation:CreateSection("Codes")
	section:CreateButton({
		Name = "Redeem All Codes",
		Callback = function() task.spawn(redeemAll) end,
	})
	section:CreateLabel("deimos, terror, 3years, lynn, justtakethecash, ubgliveson, freeemoteforall")
end

-- ============================================================
-- ESP
-- ============================================================
local Esp = { Enabled = false, Names = true, Health = true, Stats = true, Distance = true }
local espCache = {}

local function makeEsp(model)
	local t = {}
	t.name = Drawing.new("Text")
	t.name.Size = 15
	t.name.Center = true
	t.name.Outline = true
	t.name.OutlineColor = Color3.fromRGB(0, 0, 0)

	t.info = Drawing.new("Text")
	t.info.Size = 13
	t.info.Center = true
	t.info.Outline = true
	t.info.OutlineColor = Color3.fromRGB(0, 0, 0)

	t.hpBg = Drawing.new("Square")
	t.hpBg.Filled = true
	t.hpBg.Color = Color3.fromRGB(60, 20, 20)

	t.hpFg = Drawing.new("Square")
	t.hpFg.Filled = true
	t.hpFg.Color = Color3.fromRGB(80, 220, 120)

	espCache[model] = t
	return t
end

local function destroyEsp(t)
	for _, d in pairs(t) do
		pcall(function() d:Remove() end)
	end
end

local function clearEsp()
	for m, t in pairs(espCache) do
		destroyEsp(t)
		espCache[m] = nil
	end
end
onCleanup(clearEsp)

local function hideEsp(t)
	t.name.Visible = false
	t.info.Visible = false
	t.hpBg.Visible = false
	t.hpFg.Visible = false
end

local function updateEsp()
	if not Esp.Enabled or not _k.v or not Running then
		for _, t in pairs(espCache) do hideEsp(t) end
		return
	end

	local cam = Workspace.CurrentCamera
	if not cam then return end

	local live = Workspace:FindFirstChild("Live")
	if not live then
		for _, t in pairs(espCache) do hideEsp(t) end
		return
	end

	local seen = {}
	for _, model in ipairs(live:GetChildren()) do
		if model:IsA("Model") and model ~= LocalPlayer.Character then
			seen[model] = true
			local root = rootOf(model)
			if root then
				local sp, onscreen = cam:WorldToViewportPoint(root.Position)
				local t = espCache[model] or makeEsp(model)
				if onscreen and sp.Z > 0 then
					local sx, sy = sp.X, sp.Y

					local st = getStates()
					local ps = st and st:FindFirstChild(model.Name)
					local cd = ps and ps:FindFirstChild("CharacterData")
					local pd = ps and ps:FindFirstChild("PlayerData")

					local hp, maxHp = 0, 100
					if cd then
						hp = tonumber(myVal(cd, "Health")) or 0
						maxHp = tonumber(myVal(cd, "MaxHealth")) or 100
					else
						local hum = model:FindFirstChildOfClass("Humanoid")
						if hum then
							hp = hum.Health
							maxHp = hum.MaxHealth
						end
					end

					local style = pd and myVal(pd, "Style")
					local streak = pd and myVal(pd, "Streak")

					if Esp.Names then
						t.name.Text = model.Name
						t.name.Position = Vector2.new(sx, sy - 62)
						t.name.Visible = true
					else
						t.name.Visible = false
					end

					local parts = {}
					if Esp.Stats and style then table.insert(parts, tostring(style)) end
					if Esp.Stats and streak then table.insert(parts, "Streak " .. tostring(streak)) end
					if Esp.Distance then
						local me = rootOf(LocalPlayer.Character)
						if me then
							table.insert(parts, math.floor((me.Position - root.Position).Magnitude + 0.5) .. "m")
						end
					end
					local infoStr = table.concat(parts, " | ")
					if #infoStr > 0 then
						t.info.Text = infoStr
						t.info.Position = Vector2.new(sx, sy - 46)
						t.info.Visible = true
					else
						t.info.Visible = false
					end

					if Esp.Health and maxHp > 0 then
						local frac = math.clamp(hp / maxHp, 0, 1)
						local barH = 46
						local barX = sx - 34
						local kdAttr = model:GetAttribute("KnockedDown")
						local knocked = kdAttr == true or (type(kdAttr) == "number" and kdAttr ~= 0)

						t.hpBg.Size = Vector2.new(4, barH)
						t.hpBg.Position = Vector2.new(barX, sy - 56)
						t.hpBg.Color = knocked and Color3.fromRGB(90, 90, 90) or Color3.fromRGB(60, 20, 20)
						t.hpBg.Visible = true

						local r = math.floor(225 - 145 * frac)
						local g = math.floor(70 + 150 * frac)
						local b = math.floor(70 + 50 * frac)
						t.hpFg.Size = Vector2.new(4, math.max(1, barH * frac))
						t.hpFg.Position = Vector2.new(barX, sy - 56 + barH * (1 - frac))
						t.hpFg.Color = knocked and Color3.fromRGB(150, 150, 150) or Color3.fromRGB(r, g, b)
						t.hpFg.Visible = true
					else
						t.hpBg.Visible = false
						t.hpFg.Visible = false
					end
				else
					hideEsp(t)
				end
			else
				hideEsp(espCache[model] or makeEsp(model))
			end
		end
	end

	for model, t in pairs(espCache) do
		if not seen[model] then
			destroyEsp(t)
			espCache[model] = nil
		end
	end
end

local espConn = RunService.RenderStepped:Connect(function()
	if Running then
		updateEsp()
	end
end)
onCleanup(function() pcall(function() espConn:Disconnect() end) end)

