local FeatureTables = {
	Dodge = Dodge, Block = Block, Punch = Punch, Ult = Ult,
	Equip = Equip, Spin = Spin, Esp = Esp,
}
local RowLabels = {
	Dodge = "Auto Dodge", Block = "Auto Block", Punch = "Auto Punch",
	Ult = "Auto Ultimate (Q)", Equip = "Auto Equip Gloves",
	Spin = "Auto Spin", Esp = "ESP Master",
}

local function setRowVisual(labelText, on)
	pcall(function()
		local sg = LocalPlayer:FindFirstChild("PlayerGui")
			and LocalPlayer.PlayerGui:FindFirstChild("LootUI")
		if not sg then return end
		for _, d in ipairs(sg:GetDescendants()) do
			if d:IsA("TextButton") and d.Name == "ToggleRow" then
				local lbl = d:FindFirstChild("Label")
				if lbl and lbl.Text == labelText then
					local track = d:FindFirstChild("Track")
					if track then
						track.BackgroundColor3 = on
							and Color3.fromRGB(247, 36, 130)
							or Color3.fromRGB(64, 36, 46)
						local th = track:FindFirstChild("Thumb")
						if th then
							th.Position = on and UDim2.new(1, -20, 0.5, 0)
								or UDim2.new(0, 2, 0.5, 0)
						end
					end
				end
			end
		end
	end)
end

Genv.LinhUBG = {
	Unload = fullUnload,
	State = function()
		return {
			Dodge = Dodge.Enabled, Block = Block.Enabled, Punch = Punch.Enabled,
			Ult = Ult.Enabled, Equip = Equip.Enabled, Spin = Spin.Enabled,
			Esp = Esp.Enabled, Noclip = Misc.Noclip, InfJump = Misc.InfJump,
			HeavyEvery = Punch.HeavyEvery, BlockReleaseMs = Block.ReleaseMs,
			PunchDiag = punchDiag,
		}
	end,
	Toggle = function(key, on)
		on = on == true
		local t = FeatureTables[key]
		if not t then return false end
		t.Enabled = on
		if key == "Dodge" and on then lastPerfect = nil end
		if key == "Block" then
			lastIncoming = -math.huge
			rePressAt = nil
			if not on then releaseBlock() end
		end
		if RowLabels[key] then setRowVisual(RowLabels[key], on) end
		return true
	end,
	Set = function(key, field, val)
		local t = FeatureTables[key]
		if not t then return false end
		t[field] = val
		return true
	end,
}

